    if (wantsAttendance && requestedAttendance.length && (permissions.can_read_attendance !== true || (mode === "notice_scan" && permissions.can_print_attendance !== true))) return reply(403, { error: "غير مصرح بفحص سجلات الغياب المحددة" });
    if (wantsBehavior && requestedBehavior.length && (permissions.can_read_behavior !== true || (mode === "notice_scan" && permissions.can_print_behavior !== true))) return reply(403, { error: "غير مصرح بفحص سجلات السلوك المحددة" });
    const filterAttendance = (rows: any[]) => {
      const filtered = (rows || []).map(row => ({ ...row, records: filterAttendanceRecordMap(row.records, [...statusAllow], requestedStatuses) }))
        .filter(row => Object.keys(row.records).length > 0);
      // Student Affairs presents daily absence once only: keep the absent mark
      // in the earliest lesson of that class/date and hide repeated marks in
      // later lessons. This is a response-only projection; stored attendance
      // records and all other application sections remain unchanged.
      const seenDailyAbsences = new Set<string>();
      const periodOrder = (value: unknown) => {
        const match = String(value ?? "").match(/\d+/);
        return match ? Number(match[0]) : Number.MAX_SAFE_INTEGER;
      };
      const ordered = [...filtered].sort((a, b) =>
        String(b.date_str || "").localeCompare(String(a.date_str || "")) ||
        String(a.class_name || "").localeCompare(String(b.class_name || "")) ||
        periodOrder(a.period) - periodOrder(b.period) ||
        String(a.record_key || "").localeCompare(String(b.record_key || ""))
      );
      return ordered.map(row => {
        const records = { ...row.records };
        for (const [student, value] of Object.entries(records)) {
          const status = typeof value === "string" ? value
            : value && typeof value === "object" ? String((value as Record<string, unknown>).status || "") : "";
          if (status !== "absent") continue;
          const dailyKey = [String(row.class_name || ""), String(student), String(row.date_str || "")].join("\u001f");
          if (seenDailyAbsences.has(dailyKey)) delete records[student];
          else seenDailyAbsences.add(dailyKey);
        }
        return { ...row, records };
      }).filter(row => Object.keys(row.records).length > 0);
    };
    const filterBehavior = (rows: any[]) => (rows || []).map(row => ({ ...row, records: filterBehaviorRecordMap(row.records) })).filter(row => Object.keys(row.records).length > 0);
    const [attendance, behaviors] = await Promise.all([
      wantsAttendance && permissions.can_read_attendance && requestedAttendance.length
        ? db.from("attendance").select("record_key,date_str,class_name,period,teacher_name,records").in("class_name", requestedAttendance).gte("date_str", from).lte("date_str", to).order("date_str", { ascending: false }).limit(5000)
        : Promise.resolve({ data: [], error: null } as any),
      wantsBehavior && permissions.can_read_behavior && requestedBehavior.length
        ? db.from("behaviors").select("record_key,date_str,class_name,period,teacher_name,records").in("class_name", requestedBehavior).gte("date_str", from).lte("date_str", to).order("date_str", { ascending: false }).limit(5000)
        : Promise.resolve({ data: [], error: null } as any)
    ]);
    if (attendance.error || behaviors.error) return reply(500, { error: "تعذر تحميل التقارير" });
    return reply(200, { attendance: filterAttendance(attendance.data || []), behaviors: filterBehavior(behaviors.data || []), students: [], analytics: {}, permissions });
  }
  return reply(400, { error: "Unknown action" });
}
Deno.serve(async (req: Request) => {
  try { return await handle(req); }
  catch (e) { console.error("Student affairs request failed:", e); return reply(500, { error: "حدث خطأ داخلي. حاول لاحقاً." }); }
});

export type ReportPermissions = {
  can_read_attendance?: boolean;
  can_read_behavior?: boolean;
  can_view_analytics?: boolean;
  can_print_attendance?: boolean;
  can_print_behavior?: boolean;
  can_print_combined?: boolean;
};
export type AuthorizationError = { status: 400 | 403; message: string };

export type ReportsEntryPermissions = {
  role?: string;
  own_allowed_attendance_classes?: string[];
  own_allowed_behavior_classes?: string[];
  team_allowed_attendance_classes?: string[];
  team_allowed_behavior_classes?: string[];
  allowed_classes?: string[];
  allowed_attendance_classes?: string[];
  allowed_behavior_classes?: string[];
  attendance_statuses?: string[];
  can_read_attendance?: boolean;
  can_read_behavior?: boolean;
  can_view_analytics?: boolean;
  can_print_attendance?: boolean;
  can_print_behavior?: boolean;
  can_print_combined?: boolean;
};

function uniqueClasses(values: unknown[]): string[] {
  return [...new Set(values.map(value => String(value || "").trim()).filter(Boolean))];
}

/**
 * A Reports-tab grant enables the reporting workflow without overriding Student
 * Affairs role boundaries: supervisors keep their own classes, team leaders get
 * their own plus directly assigned team classes, and visitors get school-wide scope.
 */
export function applyReportsEntryPermissions<T extends object>(permissions: T, classes: string[], enabled: boolean): T & ReportsEntryPermissions {
  if (!enabled) return permissions as T & ReportsEntryPermissions;
  const p = permissions as T & ReportsEntryPermissions;
  const schoolClasses = uniqueClasses(classes);
  const role = String(p.role || "");
  const ownAttendance = uniqueClasses(p.own_allowed_attendance_classes || p.allowed_attendance_classes || []);
  const ownBehavior = uniqueClasses(p.own_allowed_behavior_classes || p.allowed_behavior_classes || []);
  const attendance = role === "visitor"
    ? schoolClasses
    : role === "team_leader"
      ? uniqueClasses([...ownAttendance, ...(p.team_allowed_attendance_classes || [])])
      : role === "supervisor"
        ? ownAttendance
        : schoolClasses;
  const behavior = role === "visitor"
    ? schoolClasses
    : role === "team_leader"
      ? uniqueClasses([...ownBehavior, ...(p.team_allowed_behavior_classes || [])])
      : role === "supervisor"
        ? ownBehavior
        : schoolClasses;
  return {
    ...p,
    allowed_classes: uniqueClasses([...attendance, ...behavior]),
    allowed_attendance_classes: attendance,
    allowed_behavior_classes: behavior,
    attendance_statuses: ["absent", "late", "escape", "outside"],
    can_read_attendance: true,
    can_read_behavior: true,
    can_view_analytics: true,
    can_print_attendance: true,
    can_print_behavior: true,
    can_print_combined: true,
  } as T & ReportsEntryPermissions;
}
export function authorizeReportMode(p: ReportPermissions, mode: string): AuthorizationError | null {
  const readAttendance = p.can_read_attendance === true;
  const readBehavior = p.can_read_behavior === true;
  const printAttendance = p.can_print_attendance === true && readAttendance;
  const printBehavior = p.can_print_behavior === true && readBehavior;
  if (!["view", "analytics", "print_attendance", "print_behavior", "print_combined", "notice_history", "notice_scan", "notice_issue_commit"].includes(mode)) {
    return { status: 400, message: "نوع التقرير غير صالح" };
  }
  if (mode === "notice_scan" && !((readAttendance && printAttendance) || (readBehavior && printBehavior))) {
    return { status: 403, message: "غير مصرح بفحص سجلات التنبيهات" };
  }
  if (mode === "notice_history" && !readAttendance && !readBehavior) {
    return { status: 403, message: "غير مصرح بعرض سجل التنبيهات" };
  }
  if (mode === "notice_issue_commit" && !(printAttendance || printBehavior)) {
    return { status: 403, message: "غير مصرح بإصدار التنبيهات الرسمية" };
  }
  if (mode === "view" && !readAttendance && !readBehavior) {
    return { status: 403, message: "لا تملك صلاحية عرض التقارير" };
  }
  if (mode === "analytics" && p.can_view_analytics !== true) {
    return { status: 403, message: "غير مصرح بعرض التحليلات" };
  }
  if (mode === "print_attendance" && !printAttendance) {
    return { status: 403, message: "غير مصرح بطباعة تقرير الغياب" };
  }
  if (mode === "print_behavior" && !printBehavior) {
    return { status: 403, message: "غير مصرح بطباعة تقرير السلوك" };
  }
  if (mode === "print_combined" && !(p.can_print_combined === true && printAttendance && printBehavior)) {
    return { status: 403, message: "غير مصرح بطباعة التقرير الموحد" };
  }
  return null;
}

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + "T00:00:00.000Z");
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

export const ATTENDANCE_STATUS_KEYS = ["absent", "late", "escape", "outside"] as const;
export function filterAttendanceRecordMap(records: unknown, allowedStatuses: string[], selectedStatuses?: string | string[] | null): Record<string, unknown> {
  if (!records || typeof records !== "object" || Array.isArray(records)) return {};
  const allowed = new Set(allowedStatuses.filter(x => (ATTENDANCE_STATUS_KEYS as readonly string[]).includes(x)));
  const requested = selectedStatuses == null ? null : new Set(Array.isArray(selectedStatuses) ? selectedStatuses : [selectedStatuses]);
  if (requested && Array.from(requested).some(status => !allowed.has(status))) return {};
  return Object.fromEntries(Object.entries(records as Record<string, unknown>).filter(([, value]) => {
    const status = typeof value === "string" ? value : value && typeof value === "object" ? String((value as Record<string, unknown>).status || "") : "";
    return allowed.has(status) && (!requested || requested.has(status));
  }));
}
export function behaviorTypesFromRecord(value: unknown): string[] {
  if (!value || typeof value !== "object") return value && value !== "normal" ? [String(value)] : [];
  const record = value as Record<string, unknown>;
  const raw = Array.isArray(record.types) ? record.types : Array.isArray(record.type) ? record.type : [record.type];
  return [...new Set(raw.map(String).filter(type => type && type !== "normal"))];
}
export function filterBehaviorRecordMap(records: unknown): Record<string, unknown> {
  if (!records || typeof records !== "object" || Array.isArray(records)) return {};
  return Object.fromEntries(Object.entries(records as Record<string, unknown>).filter(([, value]) => behaviorTypesFromRecord(value).length > 0));
}

export function areClassesAllowed(requested: string[], allowed: string[]): boolean {
  const allowedSet = new Set(allowed);
  return requested.every(className => allowedSet.has(className));
}

import { behaviorTypesFromRecord } from "./report_policy.ts";

export const NOTICE_ATTENDANCE_TYPES = ["absent", "late", "escape", "outside"] as const;
export const NOTICE_BEHAVIOR_TYPES = ["eating", "talking", "tools", "chaos", "sleeping", "homework", "other"] as const;
export const NOTICE_TYPES = [...NOTICE_ATTENDANCE_TYPES, ...NOTICE_BEHAVIOR_TYPES] as const;

export type NoticeEvent = { type: string; date: string; period: string; note: string };
export type NoticeHistoryRow = {
  class_name: string;
  student_name: string;
  issue_number: number;
  issued_on: string;
  events: NoticeEvent[] | unknown;
};
export type NoticeSession = {
  class_name?: string;
  date_str?: string;
  period?: number | string;
  record_key?: string;
  records?: Record<string, unknown>;
};
export type NoticeCandidate = {
  class_name: string;
  student_name: string;
  issue_number: number;
  previous_issue_on: string | null;
  period_start: string;
  period_end: string;
  events: NoticeEvent[];
};
export type BuildNoticeCandidatesInput = {
  attendance: NoticeSession[];
  behaviors: NoticeSession[];
  history: NoticeHistoryRow[];
  roster: Array<{ class_name: string; student_name: string }>;
  selected_types: string[];
  threshold: number;
  period_end: string;
};

const normalize = (value: unknown) => String(value ?? "").trim().replace(/\s+/g, " ");
const keyOf = (className: string, studentName: string) => className + String.fromCharCode(31) + studentName;
const eventKey = (className: string, studentName: string, event: NoticeEvent) =>
  [className, studentName, event.type, event.date, event.period, event.note].join(String.fromCharCode(31));

function periodOf(session: NoticeSession): string {
  const direct = session.period;
  if (direct !== undefined && direct !== null && String(direct).trim()) return String(direct);
  const match = String(session.record_key || "").match(/_p(\d+)$/);
  return match ? match[1] : "غير محددة";
}
function validDate(value: unknown, end: string): string {
  const date = String(value ?? "").slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(date) && date <= end ? date : "";
}

export function buildNoticeCandidates(input: BuildNoticeCandidatesInput): NoticeCandidate[] {
  const selected = new Set(input.selected_types.filter(type => (NOTICE_TYPES as readonly string[]).includes(type)));
  if (!selected.size || !Number.isInteger(input.threshold) || input.threshold < 1 || input.threshold > 10) return [];
  const roster = new Map<string, string>();
  for (const row of input.roster || []) {
    const cl = normalize(row.class_name), name = normalize(row.student_name);
    if (cl && name) roster.set(keyOf(cl, name), name);
  }

  const latest = new Map<string, { issue: number; date: string }>();
  const alreadyIssued = new Set<string>();
  const absenceDays = new Set<string>();
  for (const row of input.history || []) {
    const cl = normalize(row.class_name), name = normalize(row.student_name);
    if (!cl || !name) continue;
    const key = keyOf(cl, name);
    const prior = latest.get(key);
    const issue = Number(row.issue_number) || 0;
    if (!prior || issue > prior.issue || (issue === prior.issue && String(row.issued_on) > prior.date)) {
      latest.set(key, { issue, date: String(row.issued_on || "").slice(0, 10) });
    }
    if (Array.isArray(row.events)) {
      for (const raw of row.events) {
        if (!raw || typeof raw !== "object") continue;
        const event = raw as NoticeEvent;
        if (event.type && event.date && event.period !== undefined) {
          if (String(event.type) === "absent") absenceDays.add([cl, name, String(event.date).slice(0, 10)].join(String.fromCharCode(31)));
          alreadyIssued.add(eventKey(cl, name, {
            type: String(event.type), date: String(event.date), period: String(event.period), note: normalize(event.note)
          }));
        }
      }
    }
  }

  const grouped = new Map<string, { class_name: string; student_name: string; events: NoticeEvent[] }>();
  const seenEvents = new Set<string>();
  const add = (classNameRaw: unknown, rawName: unknown, type: string, dateRaw: unknown, period: string, noteRaw = "") => {
    if (!selected.has(type)) return;
    const className = normalize(classNameRaw);
    const originalName = normalize(rawName);
    const date = validDate(dateRaw, input.period_end);
    if (!className || !originalName || !date) return;
    const studentName = roster.get(keyOf(className, originalName)) || originalName;
    const studentKey = keyOf(className, studentName);
    const previousIssueDate = latest.get(studentKey)?.date || "";
    // A student's next monitoring window begins the day after their last official issue,
    // regardless of which categories were selected on that earlier issue.
    if (previousIssueDate && date <= previousIssueDate) return;
    const event: NoticeEvent = { type, date, period: normalize(period) || "غير محددة", note: normalize(noteRaw) };
    const fingerprint = eventKey(className, studentName, event);
    if (type === "absent") {
      const daily = [className, studentName, date].join(String.fromCharCode(31));
      if (absenceDays.has(daily)) return;
      absenceDays.add(daily);
    }
    if (alreadyIssued.has(fingerprint) || seenEvents.has(fingerprint)) return;
    seenEvents.add(fingerprint);
    if (!grouped.has(studentKey)) grouped.set(studentKey, { class_name: className, student_name: studentName, events: [] });
    grouped.get(studentKey)!.events.push(event);
  };

  for (const session of input.attendance || []) {
    const date = validDate(session.date_str, input.period_end);
    if (!date || !session.records || typeof session.records !== "object" || Array.isArray(session.records)) continue;
    for (const [name, raw] of Object.entries(session.records)) {
      const status = typeof raw === "string" ? raw : raw && typeof raw === "object"
        ? String((raw as Record<string, unknown>).status || (raw as Record<string, unknown>).type || "") : "";
      if ((NOTICE_ATTENDANCE_TYPES as readonly string[]).includes(status)) add(session.class_name, name, status, date, periodOf(session));
    }
  }
  for (const session of input.behaviors || []) {
    const date = validDate(session.date_str, input.period_end);
    if (!date || !session.records || typeof session.records !== "object" || Array.isArray(session.records)) continue;
    for (const [name, raw] of Object.entries(session.records)) {
      const data = raw && typeof raw === "object" ? raw as Record<string, unknown> : { type: String(raw || ""), note: "" };
      const note = String(data.note || data.description || "");
      for (const type of behaviorTypesFromRecord(data)) add(session.class_name, name, type, date, periodOf(session), type === "other" ? note : "");
    }
  }

  const result: NoticeCandidate[] = [];
  for (const [key, student] of grouped) {
    const previous = latest.get(key);
    if (student.events.length < input.threshold) continue;
    student.events.sort((a, b) => a.date.localeCompare(b.date) || a.period.localeCompare(b.period, "ar", { numeric: true }) || a.type.localeCompare(b.type));
    result.push({
      ...student,
      issue_number: (previous?.issue || 0) + 1,
      previous_issue_on: previous?.date || null,
      period_start: previous?.date
        ? new Date(new Date(previous.date + "T00:00:00.000Z").getTime() + 86400000).toISOString().slice(0, 10)
        : "2000-01-01",
      period_end: input.period_end,
    });
  }
  return result.sort((a, b) => a.class_name.localeCompare(b.class_name, "ar", { numeric: true }) || a.student_name.localeCompare(b.student_name, "ar"));
}

function isValidNoticeDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + "T00:00:00.000Z");
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

/**
 * Validate every field consumed by issue_student_affairs_notices before making
 * the privileged RPC call. This turns malformed candidates into a safe 400
 * response instead of a database exception/HTTP 500.
 */
export function validateNoticeIssueItem(value: unknown): string | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return "بنية التنبيه غير صالحة.";
  const item = value as Record<string, unknown>;
  const textValue = (key: string) => typeof item[key] === "string" ? (item[key] as string).trim() : "";
  if (!textValue("class_name")) return "اسم الصف مفقود.";
  if (!textValue("student_name")) return "اسم الطالب مفقود.";
  if (!textValue("issued_by_name")) return "اسم مصدر الإصدار مفقود.";
  if (!["admin", "teacher", "custom"].includes(textValue("issued_by_type"))) return "نوع حساب مصدر الإصدار غير صالح.";
  if (typeof item.delivered !== "boolean") return "حالة تسليم التنبيه غير صالحة.";
  if (!Number.isInteger(item.threshold) || Number(item.threshold) < 1 || Number(item.threshold) > 10) return "حد المخالفات غير صالح.";
  if (!isValidNoticeDate(item.issued_on)) return "تاريخ إصدار التنبيه غير صالح.";
  if (!isValidNoticeDate(item.period_end) || item.period_end > item.issued_on) return "نهاية فترة المخالفات تتجاوز تاريخ الإصدار أو غير صالحة.";
  if (item.period_start !== null && item.period_start !== undefined) {
    if (!isValidNoticeDate(item.period_start) || item.period_start > item.period_end) return "بداية فترة المخالفات غير صالحة.";
  }
  if (!Array.isArray(item.selected_types) || !item.selected_types.length ||
      item.selected_types.some(type => typeof type !== "string" || !(NOTICE_TYPES as readonly string[]).includes(type))) {
    return "قائمة أنواع المخالفات غير صالحة.";
  }
  if (!Array.isArray(item.events) || !item.events.length) return "لا توجد وقائع صالحة داخل التنبيه.";
  for (const raw of item.events) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return "توجد واقعة مخالفة لبنية التنبيه.";
    const event = raw as Record<string, unknown>;
    if (typeof event.type !== "string" || !(NOTICE_TYPES as readonly string[]).includes(event.type) ||
        !(item.selected_types as string[]).includes(event.type)) return "نوع إحدى الوقائع غير مطابق للأنواع المختارة.";
    if (!isValidNoticeDate(event.date) || event.date > item.period_end) return "تاريخ إحدى الوقائع غير صالح أو خارج فترة المخالفات.";
    if (typeof event.period !== "string" || !event.period.trim()) return "رقم الحصة في إحدى الوقائع مفقود.";
    if (event.note !== undefined && typeof event.note !== "string") return "ملاحظة إحدى الوقائع غير صالحة.";
  }
  return null;
}

/** Batched reads for the historical rows used when issuing Student Affairs notices. */
export type NoticeSourceTable = "attendance" | "behaviors";

const NOTICE_CLASS_ROW_LIMIT = 5000;
const NOTICE_COLUMNS = "record_key,date_str,class_name,period,records";

function limitError(year: number): Error {
  return new Error("بلغت سجلات أحد الصفوف الحد الأقصى في سنة " + year + ". لم نعتمد أي تنبيه حتى لا تكون النتائج ناقصة.");
}

/**
 * Read a year's rows for the authorized class set in one request when the
 * combined result is small. If the combined result exceeds the safe batch
 * window, retain the previous per-class limit behavior instead of truncating.
 */
export async function fetchNoticeRowsForClasses(
  db: any,
  table: NoticeSourceTable,
  classNames: string[],
  from: string,
  to: string,
  year: number,
): Promise<any[]> {
  const classes = [...new Set(classNames.map((value) => String(value)).filter(Boolean))];
  if (!classes.length) return [];

  const batch = await db.from(table)
    .select(NOTICE_COLUMNS, { count: "exact" })
    .in("class_name", classes)
    .gte("date_str", from)
    .lte("date_str", to)
    .order("date_str", { ascending: true })
    .order("class_name", { ascending: true })
    .order("record_key", { ascending: true })
    .limit(NOTICE_CLASS_ROW_LIMIT);

  if (batch.error) throw new Error("تعذر قراءة سجلات المخالفات التاريخية.");
  const batchRows: any[] = Array.isArray(batch.data) ? batch.data : [];
  const hasExactCount = typeof batch.count === "number" && Number.isFinite(batch.count);
  const total = hasExactCount ? Number(batch.count) : batchRows.length;
  const batchIsComplete = hasExactCount && total <= NOTICE_CLASS_ROW_LIMIT && batchRows.length === total;

  if (batchIsComplete) {
    const perClass = new Map<string, number>();
    for (const row of batchRows) {
      const className = String(row.class_name || "");
      if (!classes.includes(className)) throw new Error("وصل سجل من صف خارج النطاق المصرح به.");
      perClass.set(className, (perClass.get(className) || 0) + 1);
    }
    if ([...perClass.values()].some((count) => count >= NOTICE_CLASS_ROW_LIMIT)) throw limitError(year);
    return batchRows;
  }

  // The batch count is above the safe window, the returned row count is
  // incomplete, or exact count metadata is unavailable. Fall back to the old
  // per-class reads and enforce the same
  // 5,000-row ceiling independently for each class.
  const rowsByClass = new Map<string, any[]>();
  const fallbackErrors: Error[] = [];
  let classCursor = 0;
  const fallbackWorker = async () => {
    while (classCursor < classes.length) {
      const className = classes[classCursor++];
      try {
        const result = await db.from(table)
          .select(NOTICE_COLUMNS)
          .eq("class_name", className)
          .gte("date_str", from)
          .lte("date_str", to)
          .order("date_str", { ascending: true })
