  const visibleTeamIds = new Set((Array.isArray(ownTeamIds) ? ownTeamIds : []).map(String));
  return (Array.isArray(items) ? items : [])
    .filter(item => isAdmin || visibleTeamIds.has(String(item.teamId || "")))
    .map(item => ({
      teamName: String(item.teamName || ""),
      leaderName: String(item.leaderName || ""),
      className: String(item.className || ""),
      complete: item.complete === true,
      attendanceRate: item.complete === true && Number.isFinite(Number(item.attendanceRate)) ? Number(item.attendanceRate) : null,
      behaviorRate: item.complete === true && Number.isFinite(Number(item.behaviorRate)) ? Number(item.behaviorRate) : null,
      attendanceStatusCounts: item.complete === true && item.attendanceStatusCounts && typeof item.attendanceStatusCounts === "object" ? item.attendanceStatusCounts : null,
      behaviorTypeCounts: item.complete === true && item.behaviorTypeCounts && typeof item.behaviorTypeCounts === "object" ? item.behaviorTypeCounts : null,
      repeatAttendanceStudents: item.complete === true && Number.isFinite(Number(item.repeatAttendanceStudents)) ? Number(item.repeatAttendanceStudents) : null,
      repeatBehaviorStudents: item.complete === true && Number.isFinite(Number(item.repeatBehaviorStudents)) ? Number(item.repeatBehaviorStudents) : null
    }));
}

/** Server-side team membership checks for Student Affairs supervision. */
export type SupervisionTeacherRecord = {
  name: string;
  role?: string;
  permissions?: Record<string, unknown> | null;
};

/**
 * A supervisor belongs to one leader only when an explicit leader is stored.
 * Legacy records without that field continue to use the existing team-name match.
 */
export function isDirectSupervisionMember(
  teacher: SupervisionTeacherRecord,
  leaderName: string,
  leaderTeamName: string,
): boolean {
  if (!teacher || !teacher.name || teacher.name === leaderName || teacher.role === "custom") return false;
  const permissions = teacher.permissions || {};
  if (permissions.studentAffairs !== true || permissions.student_affairs_role !== "supervisor") return false;
  const explicitLeader = String(permissions.supervisor_team_leader_name || "").trim();
  if (explicitLeader) return explicitLeader === leaderName;
  return String(permissions.student_affairs_team_name || "").trim() === leaderTeamName;
}

/** Centralized Student Affairs supervision scope rules. */
export type SupervisionTeacher = {
  name: string;
  allowed_attendance_classes?: string[];
  allowed_behavior_classes?: string[];
  attendance_statuses?: string[];
  can_read_attendance?: boolean;
  can_read_behavior?: boolean;
  can_view_analytics?: boolean;
  can_print_attendance?: boolean;
  can_print_behavior?: boolean;
  can_print_combined?: boolean;
};

const ALL_ATTENDANCE_STATUSES = ["absent", "late", "escape", "outside"];

function unique(values: unknown[]): string[] {
  return [...new Set(values.map((value) => String(value || "").trim()).filter(Boolean))];
}

/** A leader may open only directly assigned team supervisors; a visitor may open any listed Student Affairs teacher. */
export function resolveSupervisionTeacher(
  role: string,
  targetName: string,
  teamMembers: SupervisionTeacher[],
  teacherDirectory: SupervisionTeacher[],
): SupervisionTeacher | null {
  const name = String(targetName || "").trim();
  if (!name) return null;
  const source = role === "visitor" ? teacherDirectory : role === "team_leader" ? teamMembers : [];
  return source.find((teacher) => teacher.name === name) || null;
}

/** Visitors have global read/analysis/print access, but no personal class ownership or competition participation. */
export function buildVisitorAccess(allClasses: string[], teacherDirectory: SupervisionTeacher[]) {
  const classes = unique(allClasses);
  return {
    role: "visitor",
    team_name: "",
    own_allowed_attendance_classes: [] as string[],
    own_allowed_behavior_classes: [] as string[],
    team_allowed_attendance_classes: [] as string[],
    team_allowed_behavior_classes: [] as string[],
    allowed_classes: classes,
    allowed_attendance_classes: classes,
    allowed_behavior_classes: classes,
    attendance_statuses: [...ALL_ATTENDANCE_STATUSES],
    can_read_attendance: true,
    can_read_behavior: true,
    can_view_analytics: true,
    can_view_competition: true,
    competition_participant: false,
    can_print_attendance: true,
    can_print_behavior: true,
    can_print_combined: true,
    team_members: [] as SupervisionTeacher[],
    teacher_directory: teacherDirectory,
  };
}

/** Resolves a selected leader only when that leader is active and is not the teacher being assigned. */
export function resolveTeamLeader(selectedName: string, targetName: string, leaders: Array<{ name: string; role?: string; studentAffairs?: boolean; teamName?: string }>) {
  const name = String(selectedName || "").trim();
  if (!name || name === String(targetName || "").trim()) return null;
  return leaders.find((leader) => leader.name === name && leader.role === "team_leader" && leader.studentAffairs === true && String(leader.teamName || "").trim()) || null;
}

/**
 * Team leaders inherit report and notice-print capabilities for a directly
 * resolved team member. The caller must resolve the target from team_members,
 * so this never grants access to teachers outside the leader's own team.
 */
export function applyTeamLeaderNoticePrintAccess<T extends Record<string, any>>(
  permissions: T,
  viewerRole: string,
  target: SupervisionTeacher | null,
  mode: string,
): T {
  if (viewerRole !== "team_leader" || !target || !["print_attendance", "print_behavior", "print_combined", "notice_scan", "notice_history", "notice_issue_commit"].includes(mode)) {
    return permissions;
  }
  return {
    ...permissions,
    can_print_attendance: true,
    can_print_behavior: true,
    can_print_combined: true,
  };
}

/** Projects an authorized colleague's report scope without changing the viewer's own assignments. */
export function projectSupervisionReportPermissions<T extends Record<string, any>>(
  base: T,
  target: SupervisionTeacher,
  visitor: boolean,
) {
  const attendance = unique(target.allowed_attendance_classes || []);
  const behavior = unique(target.allowed_behavior_classes || []);
  const statuses = unique(target.attendance_statuses || ALL_ATTENDANCE_STATUSES);
  return {
    ...base,
    allowed_classes: unique([...attendance, ...behavior]),
    allowed_attendance_classes: attendance,
    allowed_behavior_classes: behavior,
    attendance_statuses: visitor ? [...ALL_ATTENDANCE_STATUSES] : statuses,
    can_read_attendance: true,
    can_read_behavior: true,
    can_view_analytics: target.can_view_analytics === true || base.can_view_analytics === true || visitor,
    can_print_attendance: visitor || target.can_print_attendance === true,
    can_print_behavior: visitor || target.can_print_behavior === true,
    can_print_combined: visitor || target.can_print_combined === true,
    supervision_teacher_name: target.name,
  };
}

/** Batched attendance/behavior reads for Student Affairs analytics. */
export type AnalyticsSourceTable = "attendance" | "behaviors";

const BATCH_ROW_LIMIT = 5000;

export type AnalyticsBatchResult = {
  attendanceRowsByClass: Map<string, any[]>;
  attendanceSessionsByClass: Map<string, number>;
  behaviorSessionsByClass: Map<string, number>;
};

async function fetchAttendance(
  db: any,
  classes: string[],
  from: string,
  to: string,
): Promise<{ rowsByClass: Map<string, any[]>; countsByClass: Map<string, number> }> {
  const rowsByClass = new Map<string, any[]>();
  const countsByClass = new Map<string, number>();
  if (!classes.length) return { rowsByClass, countsByClass };

  const batch = await db.from("attendance")
    .select("record_key,date_str,class_name,records", { count: "exact" })
    .in("class_name", classes)
    .gte("date_str", from)
    .lte("date_str", to)
    .limit(BATCH_ROW_LIMIT);

  if (batch.error) throw new Error("تعذر تحميل التحليلات");
  const batchRows: any[] = Array.isArray(batch.data) ? batch.data : [];
  const hasExactCount = typeof batch.count === "number" && Number.isFinite(batch.count);
  const total = hasExactCount ? Number(batch.count) : batchRows.length;
  const complete = hasExactCount && total <= BATCH_ROW_LIMIT && batchRows.length === total;

  if (complete) {
    for (const className of classes) {
      rowsByClass.set(className, []);
      countsByClass.set(className, 0);
    }
    for (const row of batchRows) {
      const className = String(row.class_name || "");
      if (!classes.includes(className)) throw new Error("تعذر تحميل التحليلات");
      rowsByClass.get(className)!.push(row);
      countsByClass.set(className, (countsByClass.get(className) || 0) + 1);
    }
    return { rowsByClass, countsByClass };
  }

  // Preserve the original per-class exact session count and 5,000-row
  // response cap whenever a complete combined result cannot be proven.
  for (const className of classes) {
    rowsByClass.set(className, []);
    countsByClass.set(className, 0);
  }
  let cursor = 0;
  const errors: Error[] = [];
  const worker = async () => {
    while (cursor < classes.length) {
      const className = classes[cursor++];
      try {
        const result = await db.from("attendance")
          .select("record_key,date_str,records", { count: "exact" })
          .eq("class_name", className)
          .gte("date_str", from)
          .lte("date_str", to)
          .limit(BATCH_ROW_LIMIT);
        if (result.error) throw new Error("تعذر تحميل التحليلات");
        const rows: any[] = Array.isArray(result.data) ? result.data : [];
        rowsByClass.set(className, rows);
        countsByClass.set(className, Number.isFinite(result.count) ? Number(result.count) : rows.length);
      } catch (error) {
        errors.push(error instanceof Error ? error : new Error("تعذر تحميل التحليلات"));
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(3, classes.length) }, () => worker()));
  if (errors.length) throw errors[0];
  return { rowsByClass, countsByClass };
}

async function fetchBehaviorCounts(
  db: any,
  classes: string[],
  from: string,
  to: string,
): Promise<Map<string, number>> {
  const countsByClass = new Map<string, number>();
  if (!classes.length) return countsByClass;

  const batch = await db.from("behaviors")
    .select("class_name,record_key", { count: "exact" })
    .in("class_name", classes)
    .gte("date_str", from)
    .lte("date_str", to)
    .limit(BATCH_ROW_LIMIT);

  if (batch.error) throw new Error("تعذر تحميل التحليلات");
  const batchRows: any[] = Array.isArray(batch.data) ? batch.data : [];
  const hasExactCount = typeof batch.count === "number" && Number.isFinite(batch.count);
  const total = hasExactCount ? Number(batch.count) : batchRows.length;
  const complete = hasExactCount && total <= BATCH_ROW_LIMIT && batchRows.length === total;

  if (complete) {
    for (const className of classes) countsByClass.set(className, 0);
    for (const row of batchRows) {
      const className = String(row.class_name || "");
      if (!classes.includes(className)) throw new Error("تعذر تحميل التحليلات");
      countsByClass.set(className, (countsByClass.get(className) || 0) + 1);
    }
    return countsByClass;
  }

  // Large behavior ranges keep the old exact HEAD count per class, avoiding
  // downloading a potentially large behavior history just to count it.
  let cursor = 0;
  const errors: Error[] = [];
  const worker = async () => {
    while (cursor < classes.length) {
      const className = classes[cursor++];
      try {
        const result = await db.from("behaviors")
          .select("record_key", { count: "exact", head: true })
          .eq("class_name", className)
          .gte("date_str", from)
          .lte("date_str", to);
        if (result.error) throw new Error("تعذر تحميل التحليلات");
        countsByClass.set(className, Number.isFinite(result.count) ? Number(result.count) : 0);
      } catch (error) {
        errors.push(error instanceof Error ? error : new Error("تعذر تحميل التحليلات"));
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(3, classes.length) }, () => worker()));
  if (errors.length) throw errors[0];
  return countsByClass;
}

export async function fetchAnalyticsBatch(
  db: any,
  attendanceClasses: string[],
  behaviorClasses: string[],
  from: string,
  to: string,
): Promise<AnalyticsBatchResult> {
  const attendanceScope = [...new Set(attendanceClasses.map((value) => String(value)).filter(Boolean))];
  const behaviorScope = [...new Set(behaviorClasses.map((value) => String(value)).filter(Boolean))];
  const [attendance, behaviorCounts] = await Promise.all([
    fetchAttendance(db, attendanceScope, from, to),
    fetchBehaviorCounts(db, behaviorScope, from, to),
  ]);
  return {
    attendanceRowsByClass: attendance.rowsByClass,
    attendanceSessionsByClass: attendance.countsByClass,
    behaviorSessionsByClass: behaviorCounts,
  };
}

/** Batched, paginated reads for Student Affairs supervision trend reports. */
export type SupervisionTrendTable = "attendance" | "behaviors";

const PAGE_SIZE = 1000;

/**
 * Fetch rows for all authorized classes in one query per page rather than
 * issuing a serial request for every class. Stable ordering prevents page
 * boundaries from moving between rows that share the same date.
 */
export async function fetchSupervisionTrendRows(
  db: any,
  table: SupervisionTrendTable,
  classNames: string[],
  from: string,
  to: string,
): Promise<any[]> {
  const classes = [...new Set(classNames.map((value) => String(value)).filter(Boolean))];
  if (!classes.length) return [];

  const rows: any[] = [];
  for (let offset = 0; ; offset += PAGE_SIZE) {
    const { data, error } = await db.from(table)
      .select("date_str,class_name,records")
      .in("class_name", classes)
      .gte("date_str", from)
      .lte("date_str", to)
      .order("date_str", { ascending: true })
      .order("class_name", { ascending: true })
      .order("record_key", { ascending: true })
      .range(offset, offset + PAGE_SIZE - 1);
    if (error) throw error;

    const page = data || [];
    rows.push(...page);
    if (page.length < PAGE_SIZE) break;
  }
  return rows;
}

export type AppPrincipalType = "admin" | "teacher" | "custom";

export interface AppPrincipalInput {
  type: unknown;
  name: unknown;
  permissions?: unknown;
  mustChangePin?: unknown;
}

export interface AppPrincipal {
  type: AppPrincipalType;
  name: string;
  permissions: Record<string, unknown>;
  mustChangePin: boolean;
}

const SECRET_FIELD = /(pin|hash|salt|token|secret|password|credential|api.?key|private.?key)/i;

export function isValidAppPin(value: unknown): value is string {
  return typeof value === "string" && /^[0-9]{4,10}$/.test(value);
}

function removeSecretFields(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(removeSecretFields);
  if (!value || typeof value !== "object") return value;
  const clean: Record<string, unknown> = {};
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    if (!SECRET_FIELD.test(key)) clean[key] = removeSecretFields(nested);
  }
  return clean;
}

export function projectAppPrincipal(input: AppPrincipalInput): AppPrincipal | null {
  const type = input.type;
  const name = typeof input.name === "string" ? input.name.trim() : "";
  if ((type !== "admin" && type !== "teacher" && type !== "custom") || !name) return null;
  const source = input.permissions && typeof input.permissions === "object" && !Array.isArray(input.permissions)
    ? input.permissions
    : {};
  const permissions = removeSecretFields(source) as Record<string, unknown>;
  return { type, name, permissions, mustChangePin: input.mustChangePin === true };
}

export function isValidAppSessionToken(value: unknown): value is string {
  return typeof value === "string" && /^[a-f0-9]{64}$/i.test(value);
}

export function isAppSessionActive(expiresAt: unknown, now = Date.now()): boolean {
  if (typeof expiresAt !== "string") return false;
  const expiry = Date.parse(expiresAt);
  return Number.isFinite(expiry) && expiry > now;
}


/** Create an opaque 256-bit bearer token. Store only its SHA-256 digest server-side. */
export function createAppSessionToken(): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(32)))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/** Hash a validated bearer token before looking it up in a session store. */
export async function hashAppSessionToken(token: unknown): Promise<string> {
  if (!isValidAppSessionToken(token)) throw new TypeError("Invalid application session token");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/** Accept only a single well-formed Bearer token; never treat the public API key as a session. */
export function extractAppBearerToken(header: unknown): string | null {
  if (typeof header !== "string") return null;
  const match = /^Bearer ([a-f0-9]{64})$/i.exec(header.trim());
  return match ? match[1].toLowerCase() : null;
}


export interface AppLoginCandidate extends AppPrincipalInput {
  hash: unknown;
  salt: unknown;
}

/**
 * Resolve an application identity without coupling it to Student Affairs access.
 * Candidate order is normalized to the legacy login precedence: admin, custom, teacher.
 * The caller supplies the server-side credential verifier; raw credentials never leave this module.
 */
export async function resolveAppPrincipal(
  pin: unknown,
  candidates: AppLoginCandidate[],
  verify: (pin: string, salt: string, hash: string) => Promise<boolean>,
): Promise<AppPrincipal | null> {
  if (!isValidAppPin(pin) || !Array.isArray(candidates)) return null;
  const priority: Record<AppPrincipalType, number> = { admin: 0, custom: 1, teacher: 2 };
  const ordered = candidates
    .filter((candidate) =>
      (candidate.type === "admin" || candidate.type === "custom" || candidate.type === "teacher") &&
      typeof candidate.name === "string" && candidate.name.trim() !== "" &&
      typeof candidate.hash === "string" && candidate.hash.length > 0 &&
      typeof candidate.salt === "string" && candidate.salt.length > 0
    )
    .slice()
    .sort((a, b) => priority[a.type as AppPrincipalType] - priority[b.type as AppPrincipalType]);
  for (const candidate of ordered) {
    if (await verify(pin, candidate.salt as string, candidate.hash as string)) {
      return projectAppPrincipal(candidate);
    }
  }
  return null;
}


export interface AppSessionRecord {
  token_hash: string;
  principal_type: AppPrincipalType;
  principal_name: string;
  expires_at: string;
}

export interface AppSessionStore {
  deleteExpired(beforeIso: string): Promise<void>;
  insert(record: AppSessionRecord): Promise<void>;
  findByTokenHash(tokenHash: string): Promise<AppSessionRecord | null>;
  deleteByTokenHash(tokenHash: string): Promise<void>;
}

export interface ActiveAppSession {
  tokenHash: string;
  principal: { type: AppPrincipalType; name: string };
  expiresAt: string;
}

/** Issue an app-only session. Store only the token digest, never the bearer token. */
export async function issueAppSession(
  store: AppSessionStore,
  principal: AppPrincipal,
  now = Date.now(),
  ttlHours = 8,
): Promise<{ token: string; expires_at: string }> {
  if (!projectAppPrincipal(principal) || !Number.isFinite(now) || !Number.isFinite(ttlHours) || ttlHours <= 0 || ttlHours > 24) {
    throw new TypeError("Invalid application session parameters");
  }
  const token = createAppSessionToken();
  const tokenHash = await hashAppSessionToken(token);
  const expiresAt = new Date(now + ttlHours * 60 * 60 * 1000).toISOString();
  await store.deleteExpired(new Date(now).toISOString());
  await store.insert({
    token_hash: tokenHash,
    principal_type: principal.type,
    principal_name: principal.name,
    expires_at: expiresAt,
  });
  return { token, expires_at: expiresAt };
}

/** Validate a general-app bearer session without applying Student Affairs authorization. */
export async function readAppSession(
  store: AppSessionStore,
  authorization: unknown,
  now = Date.now(),
): Promise<ActiveAppSession | null> {
  const token = extractAppBearerToken(authorization);
  if (!token || !Number.isFinite(now)) return null;
  const tokenHash = await hashAppSessionToken(token);
  const record = await store.findByTokenHash(tokenHash);
  if (!record || !isAppSessionActive(record.expires_at, now)) return null;
  const principal = projectAppPrincipal({ type: record.principal_type, name: record.principal_name });
  if (!principal) return null;
  return { tokenHash, principal: { type: principal.type, name: principal.name }, expiresAt: record.expires_at };
}

/** Revoke exactly the session represented by the supplied bearer header. */
export async function revokeAppSession(store: AppSessionStore, authorization: unknown): Promise<boolean> {
  const token = extractAppBearerToken(authorization);
  if (!token) return false;
  await store.deleteByTokenHash(await hashAppSessionToken(token));
  return true;
}

import type { AppSessionRecord, AppSessionStore } from "./app_auth_policy.ts";

type StoreError = unknown;

interface QueryResult<T> {
  data: T | null;
  error: StoreError;
}

interface DeleteResult {
  error: StoreError;
}

interface DeleteFilter {
  lte(column: string, value: string): PromiseLike<DeleteResult>;
  eq(column: string, value: string): PromiseLike<DeleteResult>;
}

interface SelectFilter {
  maybeSingle(): PromiseLike<QueryResult<AppSessionRecord>>;
}

interface SelectBuilder {
  eq(column: string, value: string): SelectFilter;
}

interface AppSessionsTable {
  delete(): DeleteFilter;
  insert(record: AppSessionRecord): PromiseLike<DeleteResult>;
  select(columns: string): SelectBuilder;
}

export interface AppSessionDatabaseClient {
  from(table: "app_sessions"): AppSessionsTable;
}

const SESSION_COLUMNS = "token_hash,principal_type,principal_name,expires_at";

function throwStoreError(operation: string, error: StoreError): void {
  if (error) throw new Error(`App session store ${operation} failed`);
}

function isSessionRecord(value: unknown): value is AppSessionRecord {
  if (!value || typeof value !== "object") return false;
  const row = value as Record<string, unknown>;
  return typeof row.token_hash === "string" &&
    /^[a-f0-9]{64}$/.test(row.token_hash) &&
    (row.principal_type === "admin" || row.principal_type === "teacher" || row.principal_type === "custom") &&
    typeof row.principal_name === "string" && row.principal_name.trim().length > 0 &&
    typeof row.expires_at === "string" && Number.isFinite(Date.parse(row.expires_at));
}

/**
 * Supabase adapter for the dedicated general-app session table.
 * The caller must supply a server-side client authenticated with the service role.
 * This adapter is intentionally not wired into the live function until the
 * app_sessions migration is reviewed and tested in an isolated database.
 */
export function createSupabaseAppSessionStore(client: AppSessionDatabaseClient): AppSessionStore {
  return {
    async deleteExpired(beforeIso) {
      const { error } = await client.from("app_sessions").delete().lte("expires_at", beforeIso);
      throwStoreError("expired-session cleanup", error);
    },

    async insert(record) {
      const { error } = await client.from("app_sessions").insert(record);
      throwStoreError("session insert", error);
    },

    async findByTokenHash(tokenHash) {
      if (!/^[a-f0-9]{64}$/.test(tokenHash)) return null;
      const { data, error } = await client.from("app_sessions")
        .select(SESSION_COLUMNS)
        .eq("token_hash", tokenHash)
        .maybeSingle();
      throwStoreError("session lookup", error);
      return isSessionRecord(data) ? data : null;
    },

    async deleteByTokenHash(tokenHash) {
      if (!/^[a-f0-9]{64}$/.test(tokenHash)) return;
      const { error } = await client.from("app_sessions").delete().eq("token_hash", tokenHash);
      throwStoreError("session revocation", error);
    },
  };
}

export const APP_DATA_TABLES = [
  "classes",
  "students",
  "teachers",
  "attendance",
  "behaviors",
  "school_settings",
  "duty_reports",
] as const;

export type AppDataTable = typeof APP_DATA_TABLES[number];
export type AppDataOperation = "read" | "write" | "delete";
export type AppDataPrincipal = {
  type: "admin" | "teacher" | "custom";
  name: string;
  permissions?: Record<string, unknown>;
};
export type AppDataScope = {
  /** General class/roster scope: active timetable plus explicit school-affairs grants. */
  allowedClasses: readonly string[];
  /** Separate, explicitly granted attendance scope; never accepted from request JSON. */
  allowedAttendanceClasses?: readonly string[];
  /** Separate, explicitly granted behavior scope; never accepted from request JSON. */
  allowedBehaviorClasses?: readonly string[];
};

const TABLE_FIELDS: Record<AppDataTable, readonly string[]> = {
  classes: ["name"],
  students: ["class_name", "student_name"],
  teachers: ["name", "role", "permissions", "must_change_pin"],
  attendance: ["record_key", "date_str", "class_name", "period", "teacher_name", "records", "updated_at"],
  behaviors: ["record_key", "date_str", "class_name", "period", "teacher_name", "records", "updated_at"],
  school_settings: ["key", "value"],
  duty_reports: ["id", "date_str", "day_num", "period", "class_name", "subject", "teacher_name", "reported_by", "status", "reviewed_by", "reviewed_at", "created_at"],
};

const SECRET_KEY = /(pin|hash|salt|token|secret|password|credential|api.?key|private.?key)/i;
function isSecretField(key: string): boolean {
  return !/^must_?change_?pin$/i.test(key) && !/^mustChangePin$/i.test(key) && SECRET_KEY.test(key);
}
const ALLOWED_TABLES = new Set<string>(APP_DATA_TABLES);

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function cleanSecrets(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(cleanSecrets);
  if (!isRecord(value)) return value;
  const output: Record<string, unknown> = {};
  for (const [key, nested] of Object.entries(value)) {
    if (!isSecretField(key)) output[key] = cleanSecrets(nested);
  }
  return output;
}

function normalizeClasses(values?: readonly string[]): Set<string> {
  return new Set((values || []).map((value) => String(value).trim()).filter(Boolean));
}

export function allowedAppDataFields(table: AppDataTable): readonly string[] {
  return TABLE_FIELDS[table];
}

export function authorizeAppDataOperation(
  principal: AppDataPrincipal | null,
  tableValue: unknown,
  operation: AppDataOperation,
  row: unknown = null,
  scope?: AppDataScope,
): boolean {
  if (!principal || !principal.name?.trim() ||
    (principal.type !== "admin" && principal.type !== "teacher" && principal.type !== "custom") ||
    (operation !== "read" && operation !== "write" && operation !== "delete") ||
    !ALLOWED_TABLES.has(String(tableValue))) return false;
  const table = tableValue as AppDataTable;

  // Deletes are deliberately held back for the existing tombstone/transfer workflows.
  if (operation === "delete") return false;

  if (table === "school_settings") {
    // PIN records are handled only by dedicated authentication actions.
    if (isRecord(row) && row.key === "admin_pin") return false;
    if (operation === "read" && row === null) return principal.type === "admin";
    if (operation === "write") return principal.type === "admin" &&
      isRecord(row) && (row.key === "duty_module" || row.key === "custom_categories");
    return principal.type === "admin";
  }

  if (principal.type === "admin") return true;

  const permissions = principal.permissions || {};
  const classes = normalizeClasses(scope?.allowedClasses);
  const attendanceClasses = normalizeClasses(scope?.allowedAttendanceClasses ?? scope?.allowedClasses);
  const behaviorClasses = normalizeClasses(scope?.allowedBehaviorClasses ?? scope?.allowedClasses);
  const className = isRecord(row) ? String(row.class_name || "") : "";

  if (table === "classes" || table === "students") {
    if (operation !== "read") return false;
    return classes.size > 0 && (table === "classes"
      ? (row === null || (isRecord(row) && classes.has(String(row.name || ""))))
      : (row === null || classes.has(className)));
  }

  if (table === "teachers") {
    return operation === "read" && isRecord(row) && String(row.name || "") === principal.name;
  }

  if (table === "attendance" || table === "behaviors") {
    const permissionKey = table === "attendance" ? "attendance" : "behavior";
    // Permissions must be explicitly granted by the current server-loaded teacher profile.
    const enabled = permissions[permissionKey] === true;
    const tableClasses = table === "attendance" ? attendanceClasses : behaviorClasses;
    if (!enabled || !isRecord(row) || !tableClasses.has(className)) return false;
    if (operation === "read") return true;
    return operation === "write" && String(row.teacher_name || "") === principal.name;
  }

  if (table === "duty_reports") {
    return operation === "read" && permissions.duty === true &&
      isRecord(row) && classes.has(className);
  }

  return false;
}

/** Filter both columns and nested secret-like fields before any response reaches a browser. */
export function projectAppDataRow(table: AppDataTable, row: unknown): Record<string, unknown> | null {
  if (!isRecord(row)) return null;
  const allowed = new Set(TABLE_FIELDS[table]);
  const projected: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) {
    if (allowed.has(key) && !isSecretField(key)) projected[key] = cleanSecrets(value);
  }
  if (table === "school_settings" && projected.key === "admin_pin") return null;
  return projected;
}

export function validateAppDataWriteRows(
  table: AppDataTable,
  rows: unknown,
): Record<string, unknown>[] | null {
  if (!Array.isArray(rows) || rows.length < 1 || rows.length > 500) return null;
  const allowed = new Set(TABLE_FIELDS[table]);
  const output: Record<string, unknown>[] = [];
  for (const value of rows) {
    if (!isRecord(value)) return null;
    const keys = Object.keys(value);
    if (!keys.length || keys.some((key) => !allowed.has(key) || isSecretField(key))) return null;
    const projected = projectAppDataRow(table, value);
    if (!projected) return null;
    output.push(projected);
  }
  return output;
}

import {
  APP_DATA_TABLES,
  allowedAppDataFields,
  authorizeAppDataOperation,
  projectAppDataRow,
  type AppDataPrincipal,
  type AppDataScope,
  type AppDataTable,
} from "./app_data_gateway_policy.ts";
import { isAppDataGatewayDate } from "./app_data_gateway_validation.ts";

type SessionIdentity = { principal: { type: string; name: string } } | null;
type GatewayDependencies = {
  db: { from(table: string): any };
  headers: HeadersInit;
  readSession(authorization: string | null): Promise<SessionIdentity>;
  currentPrincipal(type: string, name: string): Promise<AppDataPrincipal | null>;
  resolveScope(principal: AppDataPrincipal): Promise<AppDataScope>;
};

function gatewayReply(status: number, body: Record<string, unknown>, headers: HeadersInit): Response {
  return new Response(JSON.stringify(body), { status, headers });
}

/** HTTP read handler with injectable identity/scope/database dependencies for isolated integration tests. */
export async function handleAppDataGatewayRead(
  req: Request,
  body: any,
  deps: GatewayDependencies,
): Promise<Response> {
  const session = await deps.readSession(req.headers.get("authorization"));
  if (!session) return gatewayReply(401, { error: "انتهت الجلسة. أعد تسجيل الدخول." }, deps.headers);
  const principal = await deps.currentPrincipal(session.principal.type, session.principal.name);
  if (!principal) return gatewayReply(401, { error: "تعذر التحقق من صلاحية الحساب الحالية." }, deps.headers);

  const tableValue = body?.table;
  if (typeof tableValue !== "string" || !(APP_DATA_TABLES as readonly string[]).includes(tableValue)) {
    return gatewayReply(400, { error: "نوع البيانات المطلوب غير مدعوم." }, deps.headers);
  }
  const table = tableValue as AppDataTable;
  if (body?.offset !== undefined && (!Number.isInteger(body.offset) || body.offset < 0 || body.offset > 100000)) {
    return gatewayReply(400, { error: "موضع الصفحة غير صالح." }, deps.headers);
  }
  if (body?.limit !== undefined && (!Number.isInteger(body.limit) || body.limit < 1 || body.limit > 500)) {
    return gatewayReply(400, { error: "حجم الصفحة غير صالح." }, deps.headers);
  }
  const offset = body?.offset ?? 0;
  const limit = body?.limit ?? 200;
  const fromDate = body?.from_date;
  const toDate = body?.to_date;
  if ((fromDate !== undefined && !isAppDataGatewayDate(fromDate)) ||
      (toDate !== undefined && !isAppDataGatewayDate(toDate)) ||
      ((fromDate !== undefined || toDate !== undefined) && table !== "attendance" && table !== "behaviors") ||
      (fromDate && toDate && fromDate > toDate)) {
    return gatewayReply(400, { error: "نطاق التاريخ غير صالح." }, deps.headers);
  }

  const scope: AppDataScope = principal.type === "admin" || table === "teachers" || table === "school_settings"
    ? { allowedClasses: [] }
    : await deps.resolveScope(principal);
  const tableClasses = table === "attendance" ? (scope.allowedAttendanceClasses || scope.allowedClasses) :
    table === "behaviors" ? (scope.allowedBehaviorClasses || scope.allowedClasses) : scope.allowedClasses;
  const firstClass = tableClasses[0] || "";
  const probe: Record<string, unknown> | null =
    table === "classes" ? { name: firstClass } :
    table === "students" || table === "attendance" || table === "behaviors" || table === "duty_reports"
      ? { class_name: firstClass, teacher_name: principal.name } :
    table === "teachers" ? { name: principal.name } : null;
  if (!authorizeAppDataOperation(principal, table, "read", probe, scope)) {
    return gatewayReply(403, { error: "ليست لديك صلاحية قراءة هذا النوع من البيانات." }, deps.headers);
  }

  let requestedClassName: string | undefined;
  if (body?.class_name !== undefined) {
    if (typeof body.class_name !== "string" ||
        !["classes", "students", "attendance", "behaviors", "duty_reports"].includes(table)) {
      return gatewayReply(400, { error: "مرشح الصف غير صالح لهذا النوع من البيانات." }, deps.headers);
    }
    requestedClassName = body.class_name.trim();
    if (!requestedClassName || requestedClassName.length > 120 ||
      (principal.type !== "admin" && !tableClasses.includes(requestedClassName))) {
      return gatewayReply(403, { error: "الصف المطلوب خارج نطاق صلاحيات الحساب." }, deps.headers);
    }
  }

  let query: any = deps.db.from(table).select(allowedAppDataFields(table).join(","));
  if (principal.type !== "admin") {
    if (table === "teachers") query = query.eq("name", principal.name);
    else if (table === "school_settings") {
      return gatewayReply(403, { error: "قراءة إعدادات النظام للمدير فقط." }, deps.headers);
    } else if (table === "classes") {
      if (!scope.allowedClasses.length) return gatewayReply(200, { rows: [], next_offset: null }, deps.headers);
      query = query.in("name", scope.allowedClasses);
    } else if (["students", "attendance", "behaviors", "duty_reports"].includes(table)) {
      if (!tableClasses.length) return gatewayReply(200, { rows: [], next_offset: null }, deps.headers);
      query = query.in("class_name", tableClasses);
    }
  }
  if (requestedClassName !== undefined) {
    query = table === "classes" ? query.eq("name", requestedClassName) : query.eq("class_name", requestedClassName);
  }
  if (table === "school_settings" && principal.type === "admin") {
    query = query.neq("key", "admin_pin");
  }
  if (table === "attendance" || table === "behaviors") {
    if (fromDate) query = query.gte("date_str", fromDate);
    if (toDate) query = query.lte("date_str", toDate);
    query = query.order("record_key", { ascending: true });
  } else if (table === "classes") query = query.order("name", { ascending: true });
  else if (table === "students") query = query.order("class_name", { ascending: true }).order("student_name", { ascending: true });
  else if (table === "teachers") query = query.order("name", { ascending: true });
  else if (table === "duty_reports") query = query.order("created_at", { ascending: true }).order("id", { ascending: true });
  else query = query.order("key", { ascending: true });

  const { data, error } = await query.range(offset, offset + limit - 1);
  if (error) throw new Error("App data gateway read failed");
  const rows = (data || []).map((row: unknown) => projectAppDataRow(table, row)).filter(Boolean);
  return gatewayReply(200, { rows, next_offset: rows.length === limit ? offset + rows.length : null }, deps.headers);
}

/** Strict ISO calendar date validation for gateway filters. */
export function isAppDataGatewayDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + "T00:00:00.000Z");
  return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

import { mergeAppDataClassScopes, projectAssignedClassScope } from "./app_data_gateway_scope.ts";
import type { AppDataScope } from "./app_data_gateway_policy.ts";

export type AppDataScopePrincipal = {
  type: string;
  name: string;
  permissions?: Record<string, unknown>;
};

type QueryResult = { data: any; error: unknown };
type ScopeDatabase = { from(table: string): any };

/** Resolve a teacher's data scope exclusively from server-side timetable and grants. */
export async function resolveAppDataScope(
  principal: AppDataScopePrincipal,
  db: ScopeDatabase,
): Promise<AppDataScope> {
  if (principal.type !== "teacher" && principal.type !== "custom") return { allowedClasses: [] };

  const { data: versions, error: versionError } = await db.from("timetable_weekly_versions")
    .select("id").eq("status", "active").limit(2) as QueryResult;
  if (versionError) throw new Error("Unable to resolve active timetable version");

  let timetableClasses: string[] = [];
  if (versions?.length === 1 && versions[0]?.id) {
    const { data: cells, error: cellsError } = await db.from("timetable_weekly_cells")
      .select("matched_teacher_name,match_status,cell_status,class_sections")
      .eq("version_id", versions[0].id)
      .eq("matched_teacher_name", principal.name)
      .eq("match_status", "matched")
      .eq("cell_status", "teaching")
      .limit(500) as QueryResult;
    if (cellsError) throw new Error("Unable to resolve teacher timetable assignments");
    if ((cells || []).length < 500) timetableClasses = projectAssignedClassScope(cells || [], principal.name);
  }

  const { data: grants, error: grantError } = await db.from("student_affairs_permissions")
    .select("allowed_classes,allowed_attendance_classes,allowed_behavior_classes,can_read_attendance,can_read_behavior")
    .eq("principal_type", principal.type)
    .eq("principal_name", principal.name)
    .maybeSingle() as QueryResult;
  if (grantError) throw new Error("Unable to resolve explicit school-affairs class grants");

  const hasStudentAffairsAccess = principal.permissions?.studentAffairs === true ||
    principal.permissions?.admin === true;
  const explicitGeneral = principal.permissions?.studentAffairs === true ? grants?.allowed_classes : [];
  const explicitAttendance = grants?.can_read_attendance === true ? grants.allowed_attendance_classes : [];
  const explicitBehavior = grants?.can_read_behavior === true ? grants.allowed_behavior_classes : [];

  return mergeAppDataClassScopes(timetableClasses, {
    allowed_classes: explicitGeneral,
    allowed_attendance_classes: explicitAttendance,
    allowed_behavior_classes: explicitBehavior,
    can_read_attendance: grants?.can_read_attendance,
    can_read_behavior: grants?.can_read_behavior,
  }, hasStudentAffairsAccess);
}

export type TimetableScopeCell = {
  matched_teacher_name?: unknown;
  match_status?: unknown;
  cell_status?: unknown;
  class_sections?: unknown;
};

/**
 * Resolve only explicitly matched teaching placements for the exact authenticated
 * principal name. Free periods, duties, unmatched rows, and other teachers never
 * grant student-data scope.
 */
export function projectAssignedClassScope(
  rows: readonly TimetableScopeCell[],
  principalName: string,
): string[] {
  const name = principalName.trim();
  if (!name || !Array.isArray(rows)) return [];
  const classes = new Set<string>();
  for (const row of rows) {
    if (row?.matched_teacher_name !== name ||
      row.match_status !== "matched" ||
      row.cell_status !== "teaching" ||
      !Array.isArray(row.class_sections)) continue;
    for (const value of row.class_sections) {
      if (typeof value !== "string") continue;
      const className = value.trim();
      if (className && className.length <= 120) classes.add(className);
    }
  }
  return [...classes].sort((a, b) => a.localeCompare(b, "en"));
}

export type ExplicitAppDataClassGrants = {
  allowed_classes?: unknown;
  allowed_attendance_classes?: unknown;
  allowed_behavior_classes?: unknown;
  can_read_attendance?: unknown;
  can_read_behavior?: unknown;
};

function cleanClassNames(values: unknown): string[] {
  if (!Array.isArray(values)) return [];
  return [...new Set(values.filter((value): value is string =>
    typeof value === "string" && value.trim().length > 0 && value.trim().length <= 120
  ).map(value => value.trim()))].sort((a, b) => a.localeCompare(b, "en"));
}

/** Combine trusted timetable assignments with separately granted Student Affairs scopes. */
export function mergeAppDataClassScopes(
  timetableClasses: readonly string[],
  grants: ExplicitAppDataClassGrants | null,
  hasStudentAffairsAccess: boolean,
): { allowedClasses: string[]; allowedAttendanceClasses: string[]; allowedBehaviorClasses: string[] } {
  // The same master gate used by the existing Student Affairs session actions
  // must apply before any dedicated class grant can expand access.
  const general = hasStudentAffairsAccess ? cleanClassNames(grants?.allowed_classes) : [];
  const attendance = !hasStudentAffairsAccess || grants?.can_read_attendance !== true ? [] :
    Array.isArray(grants?.allowed_attendance_classes)
      ? cleanClassNames(grants?.allowed_attendance_classes) : general;
  const behavior = !hasStudentAffairsAccess || grants?.can_read_behavior !== true ? [] :
    Array.isArray(grants?.allowed_behavior_classes)
      ? cleanClassNames(grants?.allowed_behavior_classes) : general;
  return {
    allowedClasses: cleanClassNames([...timetableClasses, ...general]),
    allowedAttendanceClasses: cleanClassNames([...timetableClasses, ...attendance]),
    allowedBehaviorClasses: cleanClassNames([...timetableClasses, ...behavior]),
  };
}

export const REPORT_PERMISSION_KEYS = [
  "reportMorningAssemblyLateness",
  "reportStudentAffairs",
  "reportComprehensiveAbsence",
  "reportClassLatenessFollowup",
] as const;

export type ReportPermissionKey = typeof REPORT_PERMISSION_KEYS[number];

export function hasExplicitReportPermissions(permissions: Record<string, unknown> | null | undefined): boolean {
  const value = permissions && typeof permissions === "object" ? permissions : {};
  return REPORT_PERMISSION_KEYS.some((key) => Object.prototype.hasOwnProperty.call(value, key));
}

/** Explicit per-report flags take precedence over the legacy broad reports flag. */
export function canAccessReportPermission(
  principalType: string,
  permissions: Record<string, unknown> | null | undefined,
  report: ReportPermissionKey,
): boolean {
  if (principalType === "admin") return true;
  const value = permissions && typeof permissions === "object" ? permissions : {};
  // A legacy broad flag cannot identify which report was approved.
  // Require an explicit grant for each report; admins retain the bypass above.
  return value[report] === true;
}

export function isAdminStudentAffairsAccessEnabled(value: unknown, now = Date.now()): boolean {
  if (!value || typeof value !== "object" || Array.isArray(value)) return true;
  const setting = value as Record<string, unknown>;
  if (setting.enabled !== false) return true;
  const expiresAt = typeof setting.expires_at === "string"
    ? Date.parse(setting.expires_at)
    : Number.NaN;
  // A timed diagnostic lock automatically expires. A missing/invalid expiry
  // remains disabled until the setting is explicitly removed or enabled.
  return Number.isFinite(expiresAt) && now >= expiresAt;
}

/**
 * Excel timetable workbook parser.
 *
 * Converts SheetJS sheet_to_json({ header: 1, defval: null }) rows into a
 * lossless import preview. It intentionally does NOT invent weekday/period
 * placements from weekly lesson counts or teacher availability notes.
 */

export type CellValue = string | number | boolean | Date | null | undefined;
export type WorkbookRows = Record<string, CellValue[][]>;

export interface SystemTeacher {
  id?: string;
  name: string;
  departmentId?: string;
  departmentName?: string;
}

export interface ImportedTeacher {
  sourceName: string;
  normalizedName: string;
  matchedTeacherId: string | null;
  matchedTeacherName: string | null;
  matchedDepartmentId?: string | null;
  matchedDepartmentName?: string | null;
  matchStatus: "matched" | "unmatched" | "ambiguous";
  aliases: string[];
  /** Structured day/period references stated in the teacher sheet's التفريغ field; semantics remain unconfirmed. */
  teacherPeriodNotes: Array<{ weekday: string; period: number }>;
  teacherPeriodNotesRaw: string;
  teacherPeriodNotesWarnings: string[];
  records: ImportedLessonRecord[];
}

export interface ImportedLessonRecord {
  id: string;
  sourceSheet: string;
  sourceRow: number;
  teacherSourceName: string;
  teacherMatchStatus: ImportedTeacher["matchStatus"];
  className: string;
  groupName: string;
  subject: string;
  duration: string;
  periodsPerWeek: number | null;
  availableRooms: string;
  cycle: string;
  sharedTeachers: string;
  rooms: string;
  raw: Record<string, CellValue>;
  weekday: string | null;
  period: number | null;
}

export interface ImportedReferenceRow {
  sourceSheet: string;
  sourceRow: number;
  values: Record<string, CellValue>;
}

export interface WorkbookImportResult {
  schemaVersion: 1;
  sourceSheets: string[];
  teachers: ImportedTeacher[];
  unmatchedTeacherNames: string[];
  ambiguousTeacherNames: string[];
  unassignedRecords: ImportedLessonRecord[];
  referenceData: Record<string, ImportedReferenceRow[]>;
  placements: ImportedLessonRecord[];
  hasWeeklyPlacements: boolean;
  warnings: string[];
  totals: {
    importedTeacherRows: number;
    importedLessonRecords: number;
    referenceRows: number;
    placementRows: number;
  };
}

const SHEET_ALIASES = {
  lessons: ["الحصص", "الحصة", "الدروس"],
  classes: ["الفصول", "الشعب", "الصفوف"],
  rooms: ["الغرف الدراسية", "الغرف", "القاعات"],
  subjects: ["المواد", "المادة"],
  teachers: ["المعلمون", "المعلمين", "المعلم"],
  classContracts: ["العقود الفصول", "عقود الفصول", "عقود الشعب"],
  contracts: ["العقد", "العقود"],
} as const;

function clean(value: CellValue): string {
  if (value === null || value === undefined) return "";
  return String(value).replace(/\u00a0/g, " ").replace(/[\u200e\u200f\u202a-\u202e]/g, "").trim();
}

export function normalizeArabicName(value: CellValue): string {
  return clean(value)
    .normalize("NFKC")
    .replace(/[\u064b-\u065f\u0670\u0640]/g, "")
    .replace(/[أإآٱ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ؤ/g, "و")
    .replace(/ئ/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[ـ.,،؛:()\[\]{}]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLocaleLowerCase("ar");
}


/** Matching-only tokens: keep the original source spelling in the import record. */
function teacherNameTokens(value: CellValue): string[] {
  return normalizeArabicName(value)
    .replace(/عبدال/g, "عبد ال")
    .replace(/(^|\s)(?:بن|ابن)(?=\s|$)/g, "$1")
    .split(/\s+/)
    .filter(Boolean);
}

function isOrderedSubsequence(needle: string[], haystack: string[]): boolean {
  if (!needle.length) return false;
  let index = 0;
  for (const token of haystack) {
    if (token === needle[index]) index++;
    if (index === needle.length) return true;
  }
  return false;
}

/**
 * The timetable workbook contains both a detailed name and a short alias,
 * while the live system commonly stores first name + family name. Prefer
 * evidence from the detailed name; use the alias as a strong fallback.
 */
function scoreTeacherCandidate(source: ImportedTeacher, candidate: SystemTeacher): number {
  const fullKey = normalizeArabicName(source.sourceName);
  const candidateKey = normalizeArabicName(candidate.name);
  if (fullKey && fullKey === candidateKey) return 120;

  const fullTokens = teacherNameTokens(source.sourceName);
  const candidateTokens = teacherNameTokens(candidate.name);
  const aliasExact = source.aliases.some((alias) => normalizeArabicName(alias) === candidateKey);
  if (!fullTokens.length || !candidateTokens.length) return aliasExact ? 82 : 0;

  let score = 0;
  if (fullTokens[0] === candidateTokens[0]) score += 35;
  if (fullTokens[fullTokens.length - 1] === candidateTokens[candidateTokens.length - 1]) score += 35;

  if (isOrderedSubsequence(candidateTokens, fullTokens)) {
    score += 20 + Math.max(0, candidateTokens.length - 2) * 4;
  }

  const isPrefix = candidateTokens.every((token, index) => fullTokens[index] === token);
  if (isPrefix) score += 25;

  const interiorMatches = candidateTokens.slice(1, -1)
    .filter((token) => fullTokens.includes(token)).length;
  score += interiorMatches * 5;

  // An exact workbook alias is useful, but cannot override stronger detailed-name evidence.
  if (aliasExact) score = Math.max(score, 82);
  return score;
}

/**
 * Explicit identity confirmations supplied by the school.
 * Keys are detailed workbook teacher names; values are existing system teacher names.
 * Short aliases are deliberately not used as keys because they may be shared.
 */
const CONFIRMED_TEACHER_LINKS: Record<string, string> = {
  [normalizeArabicName("س فيزياء")]: normalizeArabicName("محمد البشير"),
  [normalizeArabicName("محمد جمعة ناصر السعدي")]: normalizeArabicName("محمد جمعة السعدي"),
  [normalizeArabicName("محمد عبدالله حمود السعدي")]: normalizeArabicName("محمد عبدالله السعدي"),
};

/** Reuse the reviewed workbook identity-matching rules for pasted timetable day imports. */
export function matchSystemTeacherName(sourceName: string, systemTeachers: SystemTeacher[]): {
  teacherName: string | null;
  matchStatus: "matched" | "unmatched" | "ambiguous";
} {
  const source: ImportedTeacher = {
    sourceName,
    normalizedName: normalizeArabicName(sourceName),
    matchedTeacherId: null,
    matchedTeacherName: null,
    matchStatus: "unmatched",
    aliases: [sourceName],
    teacherPeriodNotes: [],
    teacherPeriodNotesRaw: "",
    teacherPeriodNotesWarnings: [],
    records: [],
  };
  const resolved = resolveSystemTeacher(source, systemTeachers);
  return {
    teacherName: resolved.teacher?.name ?? null,
    matchStatus: resolved.teacher ? "matched" : resolved.ambiguous ? "ambiguous" : "unmatched",
  };
}

function resolveSystemTeacher(
  source: ImportedTeacher,
  systemTeachers: SystemTeacher[],
): { teacher: SystemTeacher | null; ambiguous: boolean } {
  const confirmedTarget = CONFIRMED_TEACHER_LINKS[normalizeArabicName(source.sourceName)];
  if (confirmedTarget) {
    const confirmedMatches = systemTeachers.filter(
      (teacher) => normalizeArabicName(teacher.name) === confirmedTarget,
    );
    if (confirmedMatches.length === 1) return { teacher: confirmedMatches[0], ambiguous: false };
    // When the confirmed account is present, use it. If this particular school directory
    // does not contain that target, fall through to confidence-scored detailed-name matching.
    // This supports the same detailed source label in separate directories without guessing.
    if (confirmedMatches.length > 1) return { teacher: null, ambiguous: true };
  }

  const ranked = systemTeachers
    .map((teacher) => ({ teacher, score: scoreTeacherCandidate(source, teacher) }))
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || a.teacher.name.localeCompare(b.teacher.name, "ar"));

  if (!ranked.length || ranked[0].score < 78) return { teacher: null, ambiguous: false };
  const secondScore = ranked[1]?.score ?? -1;
  if (secondScore >= 78 && ranked[0].score - secondScore < 5) {
    return { teacher: null, ambiguous: true };
  }
  return { teacher: ranked[0].teacher, ambiguous: false };
}

function normalizeSubjectName(value: CellValue): string {
  const source = clean(value);
  const key = normalizeArabicName(source);
  if (!key) return "";
  if (["حصه دينيه", "دينيه"].includes(key)) return "تربية إسلامية";
  if (["عربي", "لغه عربيه", "اللغه العربيه"].includes(key)) return "اللغة العربية";
  if (["انجليزي", "انجليزيه", "لغه انجليزيه", "اللغه الانجليزيه"].includes(key)) return "اللغة الإنجليزية";
  if (["رياضيات", "الرياضيات"].includes(key)) return "الرياضيات";
  if (key === "اجتماع الاسلاميه" || key === "اجتماع التربيه الاسلاميه") return "اجتماع التربية الإسلامية";
  return source;
}

function normalizeHeader(value: CellValue): string {
  return normalizeArabicName(value).replace(/\s+/g, "");
}

function firstValue(row: Record<string, CellValue>, candidates: string[]): string {
  const wanted = new Set(candidates.map(normalizeHeader));
  for (const [key, value] of Object.entries(row)) {
    if (wanted.has(normalizeHeader(key))) {
      const text = clean(value);
      if (text) return text;
    }
  }
  return "";
}

function findHeaderRow(rows: CellValue[][]): number {
  for (let i = 0; i < Math.min(rows.length, 12); i++) {
    const values = rows[i] || [];
    const filled = values.filter((v) => clean(v)).length;
    if (filled >= 2) return i;
  }
  return -1;
}

function rowsToObjects(rows: CellValue[][]): Array<{ rowNumber: number; values: Record<string, CellValue> }> {
  const headerIndex = findHeaderRow(rows);
  if (headerIndex < 0) return [];
  const headers = (rows[headerIndex] || []).map((v, i) => clean(v) || `عمود ${i + 1}`);
  const output: Array<{ rowNumber: number; values: Record<string, CellValue> }> = [];
  for (let i = headerIndex + 1; i < rows.length; i++) {
    const cells = rows[i] || [];
    if (!cells.some((v) => clean(v))) continue;
    const values: Record<string, CellValue> = {};
    headers.forEach((header, index) => {
      if (header) values[header] = cells[index] ?? null;
    });
    output.push({ rowNumber: i + 1, values });
  }
  return output;
}

function findSheet(sheets: WorkbookRows, aliases: readonly string[]): string | null {
  const wanted = new Set(aliases.map(normalizeArabicName));
  return Object.keys(sheets).find((name) => wanted.has(normalizeArabicName(name))) || null;
}

function valueByHeader(row: Record<string, CellValue>, candidates: string[]): CellValue {
  const wanted = new Set(candidates.map(normalizeHeader));
  for (const [key, value] of Object.entries(row)) {
    if (wanted.has(normalizeHeader(key))) return value;
  }
  return null;
}

function parseCount(value: CellValue): number | null {
  const text = clean(value).replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d))).replace(",", ".");
  if (!text) return null;
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return null;
  const number = Number(match[0]);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

const SCHOOL_WEEKDAYS = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس"] as const;

/**
 * Parse day/period references in the teacher sheet's التفريغ field without
 * assigning a meaning such as free, busy, or unavailable. A separate teacher
 * clarification exists for a specific record, but the field's general semantics
 * conflict with other explicit daily teaching records and must remain unconfirmed.
 * Empty or malformed text is never expanded into any schedule state.
 */
export function parseTeacherPeriodNotes(value: CellValue): {
  periods: Array<{ weekday: string; period: number }>;
  warnings: string[];
} {
  const raw = clean(value);
  const periods: Array<{ weekday: string; period: number }> = [];
  const warnings: string[] = [];
  if (!raw) return { periods, warnings };
  const seen = new Set<string>();
  for (const part of raw.split(/[;؛]/).map((item) => item.trim()).filter(Boolean)) {
    const colon = part.indexOf(":");
    if (colon < 0) {
      warnings.push(part);
      continue;
    }
    const dayText = part.slice(0, colon).trim();
    const periodText = part.slice(colon + 1).replace(/[٠-٩]/g, (digit) => String("٠١٢٣٤٥٦٧٨٩".indexOf(digit)));
    const dayRange = dayText.split(/\s*[-–—]\s*/).map((day) => normalizeArabicName(day));
    const dayStart = SCHOOL_WEEKDAYS.findIndex((day) => normalizeArabicName(day) === dayRange[0]);
    const dayEnd = dayRange.length === 1
      ? dayStart
      : SCHOOL_WEEKDAYS.findIndex((day) => normalizeArabicName(day) === dayRange[1]);
    if (dayStart < 0 || dayEnd < dayStart) {
      warnings.push(part);
      continue;
    }
    const selectedDays = SCHOOL_WEEKDAYS.slice(dayStart, dayEnd + 1);
    const selectedPeriods: number[] = [];
    for (const token of periodText.split(/[,،]/).map((item) => item.trim()).filter(Boolean)) {
      const match = token.match(/^(\d+)\s*(?:[-–—]\s*(\d+))?$/);
      if (!match) {
        warnings.push(part);
        continue;
      }
      const first = Number(match[1]);
      const last = Number(match[2] || match[1]);
      if (first < 1 || last > 7 || last < first) {
        warnings.push(part);
        continue;
      }
      for (let period = first; period <= last; period++) selectedPeriods.push(period);
    }
    for (const weekday of selectedDays) {
      for (const period of selectedPeriods) {
        const key = weekday + ":" + period;
        if (!seen.has(key)) {
          seen.add(key);
          periods.push({ weekday, period });
        }
      }
    }
  }
  return { periods, warnings: Array.from(new Set(warnings)) };
}

function buildTeacherDirectory(
  rows: Array<{ rowNumber: number; values: Record<string, CellValue> }>,
  systemTeachers: SystemTeacher[],
): { teachers: ImportedTeacher[]; aliasMap: Map<string, Set<string>> } {
  const byId = new Map(systemTeachers.map((t) => [String(t.id ?? t.name), t]));
  const aliasMap = new Map<string, Set<string>>();
  const imported = new Map<string, ImportedTeacher>();

  for (const item of rows) {
    const name = firstValue(item.values, ["الاسم", "الإسم", "اسم"]);
    if (!name) continue;
    const shortName = firstValue(item.values, ["الاختصار", "الإختصار", "الاسم المختصر"]);
    const key = normalizeArabicName(name);
    if (!key) continue;
    const aliases = [name, shortName].filter(Boolean);
    const freeText = firstValue(item.values, ["التفريغ"]);
    const parsedFree = parseTeacherPeriodNotes(freeText);
    const current = imported.get(key) || {
      sourceName: name,
      normalizedName: key,
      matchedTeacherId: null,
      matchedTeacherName: null,
      matchStatus: "unmatched" as const,
      aliases: [],
      teacherPeriodNotes: [],
      teacherPeriodNotesRaw: "",
      teacherPeriodNotesWarnings: [],
      records: [],
    };
    current.aliases = Array.from(new Set([...current.aliases, ...aliases]));
    if (freeText) {
      current.teacherPeriodNotesRaw = current.teacherPeriodNotesRaw
        ? current.teacherPeriodNotesRaw + "; " + freeText
        : freeText;
      const merged = new Map(current.teacherPeriodNotes.map((entry) => [entry.weekday + ":" + entry.period, entry]));
      for (const entry of parsedFree.periods) merged.set(entry.weekday + ":" + entry.period, entry);
      current.teacherPeriodNotes = Array.from(merged.values());
      current.teacherPeriodNotesWarnings = Array.from(new Set([...current.teacherPeriodNotesWarnings, ...parsedFree.warnings]));
    }
    imported.set(key, current);
  }

  for (const teacher of imported.values()) {
    const resolved = resolveSystemTeacher(teacher, systemTeachers);
    if (resolved.teacher) {
      const match = resolved.teacher;
      teacher.matchedTeacherId = String(match.id ?? match.name);
      teacher.matchedTeacherName = match.name;
      teacher.matchedDepartmentId = match.departmentId || match.departmentName || null;
      teacher.matchedDepartmentName = match.departmentName || match.departmentId || null;
      teacher.matchStatus = "matched";
    } else if (resolved.ambiguous) {
      teacher.matchStatus = "ambiguous";
    }
    for (const alias of teacher.aliases) {
      const key = normalizeArabicName(alias);
      if (!aliasMap.has(key)) aliasMap.set(key, new Set());
      aliasMap.get(key)!.add(teacher.normalizedName);
    }
  }
  return { teachers: Array.from(imported.values()), aliasMap };
}

function identifyTeacher(
  sourceName: string,
  directory: ImportedTeacher[],
): ImportedTeacher | null {
  const key = normalizeArabicName(sourceName);
  if (!key) return null;
  const matches = directory.filter((teacher) =>
    teacher.aliases.some((alias) => normalizeArabicName(alias) === key)
  );
  return matches.length === 1 ? matches[0] : null;
}

function parseLessonRows(
  sheetName: string,
  rows: CellValue[][],
  directory: ImportedTeacher[],
): { records: ImportedLessonRecord[]; unassigned: ImportedLessonRecord[]; placements: ImportedLessonRecord[] } {
  const objects = rowsToObjects(rows);
  const records: ImportedLessonRecord[] = [];
  const unassigned: ImportedLessonRecord[] = [];
  const placements: ImportedLessonRecord[] = [];
  let inheritedTeacher = "";
  let inheritedClass = "";

  for (const item of objects) {
    const values = item.values;
    const teacherCell = firstValue(values, ["المعلم", "المعلمون", "اسم المعلم"]);
    const classCell = firstValue(values, ["الشعب", "الشعبة", "الفصل", "الصف"]);
    const subject = normalizeSubjectName(firstValue(values, ["المادة", "اسم المادة"]));
    const group = firstValue(values, ["المجموعة", "التقسيم"]);
    const isTeacherHeader = !!teacherCell && !classCell && !subject;
    const isClassHeader = !!classCell && !teacherCell && !subject;

    if (isTeacherHeader) {
      inheritedTeacher = teacherCell;
      continue;
    }
    if (isClassHeader) {
      inheritedClass = classCell;
      continue;
    }

    const teacherName = teacherCell || inheritedTeacher;
    const className = classCell || inheritedClass;
    if (!teacherName && !className && !subject) continue;

    const day = firstValue(values, ["اليوم", "يوم", "اليوم الدراسي"]);
    const periodText = firstValue(values, ["الحصة", "رقم الحصة", "الفترة", "رقم الفترة"]);
    const period = parseCount(periodText);
    const match = identifyTeacher(teacherName, directory);
    const record: ImportedLessonRecord = {
      id: `${normalizeArabicName(sheetName)}:${item.rowNumber}`,
      sourceSheet: sheetName,
      sourceRow: item.rowNumber,
      teacherSourceName: teacherName,
      teacherMatchStatus: match?.matchStatus || (teacherName ? "unmatched" : "unmatched"),
      className,
      groupName: group,
      subject,
      duration: firstValue(values, ["المدة", "مدة الحصة"]),
      periodsPerWeek: parseCount(valueByHeader(values, ["الحصص/الأسبوع", "الحصص الاسبوعية", "عدد الحصص"])),
      availableRooms: firstValue(values, ["الغرف الدراسية المتاحة", "الغرف المتاحة"]),
      cycle: firstValue(values, ["الدورة", "دورة"]),
      sharedTeachers: firstValue(values, ["معلم مشارك في المادة", "المعلم المشارك", "معلم مشارك"]),
      rooms: firstValue(values, ["الغرف الدراسية", "الغرفة"]),
      raw: { ...values },
      weekday: day || null,
      period: day && period !== null ? period : null,
    };
    records.push(record);
    if (match) match.records.push(record);
    else unassigned.push(record);
    if (record.weekday && record.period !== null) placements.push(record);
  }
  return { records, unassigned, placements };
}

export function parseTimetableWorkbook(
  sheets: WorkbookRows,
  systemTeachers: SystemTeacher[] = [],
): WorkbookImportResult {
  const warnings: string[] = [];
  const sourceSheets = Object.keys(sheets);
  const teacherSheet = findSheet(sheets, SHEET_ALIASES.teachers);
  const teacherRows = teacherSheet ? rowsToObjects(sheets[teacherSheet]) : [];
  const { teachers } = buildTeacherDirectory(teacherRows, systemTeachers);

  if (!teacherSheet) warnings.push("لم يتم العثور على ورقة المعلمين؛ ستحتاج مطابقة الأسماء يدوياً.");
  if (!findSheet(sheets, SHEET_ALIASES.lessons)) warnings.push("لم يتم العثور على ورقة الحصص.");

  const referenceData: Record<string, ImportedReferenceRow[]> = {};
  if (teacherSheet) {
    // Preserve all teacher-level constraints (MWD, EXH, DAYS, <a,b>, availability notes, etc.)
    // verbatim so later scheduling rules can be defined without losing source data.
    referenceData[teacherSheet] = teacherRows.map((row) => ({
      sourceSheet: teacherSheet,
      sourceRow: row.rowNumber,
      values: row.values,
    }));
  }
  for (const [key, aliases] of Object.entries(SHEET_ALIASES)) {
    const sheetName = findSheet(sheets, aliases);
    if (!sheetName || key === "teachers" || key === "lessons" || key === "contracts" || key === "classContracts") continue;
    referenceData[sheetName] = rowsToObjects(sheets[sheetName]).map((row) => ({
      sourceSheet: sheetName,
      sourceRow: row.rowNumber,
      values: row.values,
    }));
  }

  const allRecords: ImportedLessonRecord[] = [];
  const unassignedRecords: ImportedLessonRecord[] = [];
  const placements: ImportedLessonRecord[] = [];
  for (const key of ["lessons", "contracts", "classContracts"] as const) {
    const sheetName = findSheet(sheets, SHEET_ALIASES[key]);
    if (!sheetName) continue;
    const parsed = parseLessonRows(sheetName, sheets[sheetName], teachers);
    allRecords.push(...parsed.records);
    unassignedRecords.push(...parsed.unassigned);
    placements.push(...parsed.placements);
  }

  // Keep every teacher name found in lesson/contract rows visible, even when
  // the workbook's teacher directory omitted it or the system has no match.
  const unresolvedRecords: ImportedLessonRecord[] = [];
  for (const record of unassignedRecords) {
    const key = normalizeArabicName(record.teacherSourceName);
    if (!key) {
      unresolvedRecords.push(record);
      continue;
    }
    const importedMatches = teachers.filter((item) => item.aliases.some((alias) => normalizeArabicName(alias) === key));
    if (importedMatches.length > 1) {
      const ambiguousTeacher: ImportedTeacher = {
        sourceName: record.teacherSourceName,
        normalizedName: key,
        matchedTeacherId: null,
        matchedTeacherName: null,
        matchStatus: "ambiguous",
        aliases: [record.teacherSourceName],
        teacherPeriodNotes: [],
        teacherPeriodNotesRaw: "",
        teacherPeriodNotesWarnings: [],
        records: [record],
      };
      teachers.push(ambiguousTeacher);
      record.teacherMatchStatus = "ambiguous";
      unresolvedRecords.push(record);
      continue;
    }
    let teacher = importedMatches[0] || null;
    if (!teacher) {
      const systemMatches = systemTeachers.filter((item) => normalizeArabicName(item.name) === key);
      const uniqueMatch = systemMatches.length === 1 ? systemMatches[0] : null;
      teacher = {
        sourceName: record.teacherSourceName,
        normalizedName: key,
        matchedTeacherId: uniqueMatch ? String(uniqueMatch.id ?? uniqueMatch.name) : null,
        matchedTeacherName: uniqueMatch?.name ?? null,
        matchStatus: uniqueMatch ? "matched" : systemMatches.length > 1 ? "ambiguous" : "unmatched",
        aliases: [record.teacherSourceName],
        teacherPeriodNotes: [],
        teacherPeriodNotesRaw: "",
        teacherPeriodNotesWarnings: [],
        records: [],
      };
      teachers.push(teacher);
    }
    teacher.records.push(record);
    record.teacherMatchStatus = teacher.matchStatus;
    if (teacher.matchStatus !== "matched") unresolvedRecords.push(record);
  }
  unassignedRecords.splice(0, unassignedRecords.length, ...unresolvedRecords);
  const unmatchedTeacherNames = teachers.filter((t) => t.matchStatus === "unmatched").map((t) => t.sourceName);
  const ambiguousTeacherNames = teachers.filter((t) => t.matchStatus === "ambiguous").map((t) => t.sourceName);
  if (!placements.length) {
    warnings.push("لم تُعثر على أعمدة واضحة لليوم ورقم الحصة؛ عُرضت بيانات العقود والحصص دون إنشاء جدول أسبوعي افتراضي.");
  }
  if (unmatchedTeacherNames.length) warnings.push(`يوجد ${unmatchedTeacherNames.length} اسم معلم يحتاج إلى مطابقة مع سجل النظام.`);
  if (ambiguousTeacherNames.length) warnings.push(`يوجد ${ambiguousTeacherNames.length} اسم معلم ملتبس يحتاج إلى مراجعة.`);

  return {
    schemaVersion: 1,
    sourceSheets,
    teachers,
    unmatchedTeacherNames,
    ambiguousTeacherNames,
    unassignedRecords,
    referenceData,
    placements,
    hasWeeklyPlacements: placements.length > 0,
    warnings,
    totals: {
      importedTeacherRows: teachers.length,
      importedLessonRecords: allRecords.length,
      referenceRows: Object.values(referenceData).reduce((sum, rows) => sum + rows.length, 0),
      placementRows: placements.length,
    },
  };
}

/** Lossless parser for daily timetable text. Supports both labelled teacher blocks and the school's tab-separated row export. */
export const SCHOOL_WEEKDAYS = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس"] as const;
export type SchoolWeekday = typeof SCHOOL_WEEKDAYS[number];
export type TimetableCellStatus = "teaching" | "free" | "meeting" | "activity" | "other" | "unclear";
export interface ParsedTimetableCell {
  period: number; classSections: string[]; subject: string; status: TimetableCellStatus;
  sourceClass: string; sourceSubject: string; sourceStatus: string; sourceNote?: string;
}
export interface ParsedTimetableTeacher { sourceName: string; pdfPage: number | null; cells: ParsedTimetableCell[]; }
export interface ParsedTimetableDay {
  weekday: SchoolWeekday; teachers: ParsedTimetableTeacher[];
  totals: Record<TimetableCellStatus, number>; totalCells: number; warnings: string[];
}
const PERIOD_WORDS: Record<string, number> = {
  "الاولى":1,"الأولى":1,"الاول":1,"الأول":1,"الثانية":2,"الثانيه":2,
  "الثالثة":3,"الثالثه":3,"الرابعة":4,"الرابعه":4,"الخامسة":5,"الخامسه":5,
  "السادسة":6,"السادسه":6,"السابعة":7,"السابعه":7,"الثامنة":8,"الثامنه":8,"الثامن":8
};
function cleanLine(value: string): string {
  return value.replace(/\u00a0/g," ").replace(/[\u200e\u200f\u202a-\u202e]/g,"").trim();
}
function normalizedKey(value: string): string {
  return value.normalize("NFKC").replace(/[\u064b-\u065f\u0670\u0640]/g,"")
    .replace(/[أإآٱ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه").replace(/\s+/g," ").trim();
}
function weekdayFromSource(value: string): SchoolWeekday | null {
  return SCHOOL_WEEKDAYS.find((day)=>normalizedKey(day)===normalizedKey(value)) ?? null;
}
function statusFromSource(value: string): TimetableCellStatus {
  const key=normalizedKey(value);
  if (["تدريس","درس","حصة تدريس"].includes(key)) return "teaching";
  if (["فراغ","فارغ","فارغه","حصة فراغ","حصة فارغه"].includes(key)) return "free";
  if (["اجتماع","اجتماع قسم","اجتماع اداري","اجتماع الماده","اجتماع القسم","اجتماع المواد"].includes(key)) return "meeting";
  if (["نشاط","نشاط مدرسي","مناوبة"].includes(key)) return "activity";
  if (["اخري","حاله اخري","ارتباط"].includes(key)) return "other";
  if (["غير واضح","غير واضحه","غير مقروء","غير مقروءه"].includes(key)) return "unclear";
  // Unknown source labels are not safely classifiable; preserve their raw value
  // and keep them out of free-period substitution eligibility.
  return "unclear";
}
function subjectFromSource(value: string): string {
  const key=normalizedKey(value);
  if (["التربيه الاسلاميه","تربيه اسلاميه","حصه دينيه","دينيه"].includes(key)) return "التربية الإسلامية";
  if (["اللغه العربيه","عربي"].includes(key)) return "اللغة العربية";
  if (["اللغه الانجليزيه","انجليزي","انجليزيه"].includes(key)) return "اللغة الإنجليزية";
  return value.trim();
}
function parsePeriod(value: string): number | null {
  const text=normalizedKey(value).replace(/[٠-٩]/g,d=>String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
  if (/^[1-8]$/.test(text)) return Number(text);
  const normalizedWords = new Map(Object.entries(PERIOD_WORDS).map(([word, number]) => [normalizedKey(word), number]));
  return normalizedWords.get(text) ?? null;
}
function parseClassSections(value: string): string[] {
  const text=value.trim();
  if (!text || ["فراغ","فارغ","غير واضح","-"].includes(normalizedKey(text))) return [];
  const sections = text.split(/[،,؛;\n]+/).map(v=>v.trim()).filter(Boolean).flatMap((part) => {
    // Some source rows concatenate two class codes without punctuation, e.g. 6/11/7/11.
    // Interpret an even sequence of 4+ numeric slash-separated tokens as adjacent pairs.
    // Preserve ordinary two-part codes (e.g. 6/11) and any non-numeric/ambiguous source verbatim.
    const tokens = part.split("/").map(token => token.trim());
    if (tokens.length >= 4 && tokens.length % 2 === 0 && tokens.every(token => /^\d+$/.test(token))) {
      const pairs: string[] = [];
      for (let index = 0; index < tokens.length; index += 2) pairs.push(tokens[index] + "/" + tokens[index + 1]);
      return pairs;
    }
    return [part];
  });
  return Array.from(new Set(sections));
}
function emptyTotals(): Record<TimetableCellStatus,number> {
  return {teaching:0,free:0,meeting:0,activity:0,other:0,unclear:0};
}
function validateTeacherGrid(teacher: ParsedTimetableTeacher): void {
  const periods=teacher.cells.map(v=>v.period).sort((a,b)=>a-b);
  if (![7,8].includes(periods.length) || periods.some((v,i)=>v!==i+1))
    throw new Error("المعلم «"+teacher.sourceName+"» يجب أن يحتوي على 7 أو 8 حصص متتابعة دون نقص. الموجود: "+(periods.join(", ")||"لا توجد حصص")+".");
}
function parseTabularTimetableDay(day: SchoolWeekday, sourceText: string): ParsedTimetableDay | null {
  const teachers: ParsedTimetableTeacher[]=[];
  const byName=new Map<string,ParsedTimetableTeacher>();
  let recognizedRows=0;
  const lines=sourceText.split(/\r?\n/);
  for(let index=0;index<lines.length;index++){
    const raw=cleanLine(lines[index]);
    if(!raw.includes("\t")) continue;
    const fields=raw.split("\t").map(cleanLine);
    if(fields.length<6) continue;
    const rowDay=weekdayFromSource(fields[1]||"");
    if(!rowDay) continue;
    recognizedRows++;
    if(rowDay!==day) throw new Error("السطر "+(index+1)+" يخص يوم "+rowDay+" وليس يوم "+day+".");
    const sourceName=fields[0];
    const period=parsePeriod(fields[2]||"");
    if(!sourceName) throw new Error("اسم المعلم فارغ في السطر "+(index+1)+".");
    if(!period) throw new Error("رقم الحصة غير معروف في السطر "+(index+1)+": "+(fields[2]||"فارغ")+".");
    if(fields[3]===undefined||fields[4]===undefined||fields[5]===undefined||!fields[3]||!fields[4]||!fields[5]){
      throw new Error("بيانات الصف أو المادة أو الحالة ناقصة في السطر "+(index+1)+". لا أملأ البيانات الناقصة بالتخمين.");
    }
    const key=normalizedKey(sourceName);
    let teacher=byName.get(key);
    if(!teacher){teacher={sourceName,pdfPage:null,cells:[]};byName.set(key,teacher);teachers.push(teacher);}
    const sourceClass=fields[3],sourceSubject=fields[4],sourceStatus=fields[5],sourceNote=fields.slice(6).filter(Boolean).join(" | ");
    const status=statusFromSource(sourceStatus);
    const existing=teacher.cells.find(cell=>cell.period===period);
    if(existing){
      if(existing.status!==status || normalizedKey(existing.sourceSubject)!==normalizedKey(sourceSubject) || normalizedKey(existing.sourceStatus)!==normalizedKey(sourceStatus)){
        throw new Error("للمعلم «"+sourceName+"» أكثر من تكليف متعارض في الحصة "+period+" يوم "+day+". راجع الصفوف قبل الاستيراد.");
      }
      existing.classSections=Array.from(new Set([...existing.classSections,...parseClassSections(sourceClass)]));
      if(!existing.sourceClass.split(" | ").includes(sourceClass)) existing.sourceClass+=" | "+sourceClass;
      if(sourceNote && !existing.sourceNote?.split(" | ").includes(sourceNote)) existing.sourceNote=[existing.sourceNote,sourceNote].filter(Boolean).join(" | ");
      continue;
    }
    teacher.cells.push({period,classSections:parseClassSections(sourceClass),subject:subjectFromSource(sourceSubject),status,sourceClass,sourceSubject,sourceStatus,...(sourceNote?{sourceNote}:{})});
  }
  if(!recognizedRows) return null;
  for(const teacher of teachers){teacher.cells.sort((a,b)=>a.period-b.period);validateTeacherGrid(teacher);}
  const periodCount=teachers[0]?.cells.length||0;
  if(![7,8].includes(periodCount)||teachers.some(teacher=>teacher.cells.length!==periodCount))throw new Error("يجب أن يحتوي كل معلم في اليوم على العدد نفسه من الحصص (7 أو 8).");
  const totals=emptyTotals();
  for(const teacher of teachers)for(const cell of teacher.cells)totals[cell.status]++;
  const totalCells=teachers.reduce((sum,teacher)=>sum+teacher.cells.length,0);
  return {weekday:day,teachers,totals,totalCells,warnings:[]};
}
/** Parse a single day. Input may use one teacher section with seven labelled cells or one tab-separated row per teacher/period:
 * teacher name, weekday, period, class, subject, status, optional note.
 */

/** Enforce the school's reviewed teacher roster size at the import boundary. */
export function validateSchoolTeacherCount(day: ParsedTimetableDay, expectedCount: number): void {
  if (!Number.isInteger(expectedCount) || expectedCount < 1) {
    throw new Error("عدد المعلمين المتوقع غير صالح.");
  }
  if (day.teachers.length !== expectedCount) {
    throw new Error("يجب أن يحتوي يوم " + day.weekday + " على " + expectedCount +
      " معلماً بالضبط؛ الموجود " + day.teachers.length + ". راجع التفريغ قبل الحفظ.");
  }
}

export function parseTimetableDay(weekday: string, sourceText: string): ParsedTimetableDay {
  const day=weekdayFromSource(weekday);
  if (!day) throw new Error("يجب تحديد يوم دراسي صحيح من الأحد إلى الخميس.");
  if (typeof sourceText!=="string" || !sourceText.trim()) throw new Error("لم يتم إدخال نص الجدول.");
  if (sourceText.length>500000) throw new Error("نص الجدول أكبر من الحد المسموح.");
  const tabular=parseTabularTimetableDay(day,sourceText);
  if(tabular) return tabular;

  const teachers:ParsedTimetableTeacher[]=[];
  const seenNames=new Set<string>();
  const totals=emptyTotals();
  const warnings:string[]=[];
  let teacher:ParsedTimetableTeacher|null=null;
  let cell:Partial<ParsedTimetableCell>|null=null;
  let cellStartLine=0;
  const finishCell=()=>{
    if(!cell)return;
    const missing:string[]=[];
    if(cell.period===undefined)missing.push("رقم الحصة");
    if(cell.sourceClass===undefined)missing.push("الصف والشعبة");
    if(cell.sourceSubject===undefined)missing.push("المادة");
    if(cell.sourceStatus===undefined)missing.push("الحالة");
    if(missing.length)throw new Error("بيانات الحصة قرب السطر "+cellStartLine+" غير مكتملة: "+missing.join("، "));
    if(!teacher)throw new Error("تعذر ربط الحصة بمعلم قرب السطر "+cellStartLine+".");
    const sourceClass=cell.sourceClass!,sourceSubject=cell.sourceSubject!,sourceStatus=cell.sourceStatus!;
    const status=statusFromSource(sourceStatus);
    teacher.cells.push({period:cell.period!,classSections:parseClassSections(sourceClass),subject:subjectFromSource(sourceSubject),status,sourceClass,sourceSubject,sourceStatus,...(cell.sourceNote?{sourceNote:cell.sourceNote}:{})});
    totals[status]+=1;cell=null;
  };
  const finishTeacher=()=>{
    finishCell();
    if(!teacher)return;
    teacher.cells.sort((a,b)=>a.period-b.period);validateTeacherGrid(teacher);teachers.push(teacher);teacher=null;
  };
  const lines=sourceText.split(/\r?\n/);
  for(let i=0;i<lines.length;i++){
    const line=cleanLine(lines[i]);if(!line)continue;
    const dayHeading=line.match(/^(?:جدول\s+)?اليوم(?:\s+\S+)?\s*:\s*(.+)$/)||line.match(/^جدول\s+يوم\s+(.+)$/);
    if(dayHeading){
      const declaredDay=weekdayFromSource(dayHeading[1]);
      if(!declaredDay)throw new Error("اسم اليوم في العنوان غير معروف عند السطر "+(i+1)+": "+dayHeading[1]);
      if(declaredDay!==day)throw new Error("النص يحتوي على جدول يوم "+declaredDay+" بينما اليوم المختار هو "+day+".");
      continue;
    }
    const namedTeacher=line.match(/^[-•]?\s*اسم\s*المعلم\s*:\s*(.+?)\s*$/);
    const numberedTeacher=line.match(/^\s*\d+[.)]\s*(.+?)(?:\s*\(\s*صفحة\s*PDF\s*:\s*(\d+)\s*\))?\s*$/i);
    const teacherHeader=namedTeacher||numberedTeacher;
    if(teacherHeader){
      finishTeacher();
      const name=cleanLine(namedTeacher?namedTeacher[1]:numberedTeacher![1]),key=normalizedKey(name);
      if(!name||seenNames.has(key))throw new Error("اسم المعلم فارغ أو مكرر عند السطر "+(i+1)+": "+name);
      seenNames.add(key);teacher={sourceName:name,pdfPage:numberedTeacher&&numberedTeacher[2]?Number(numberedTeacher[2]):null,cells:[]};continue;
    }
    const pageOnly=line.match(/^صفحة\s*PDF\s*:\s*(\d+)$/i);
    if(pageOnly&&teacher&&!teacher.cells.length&&!cell){teacher.pdfPage=Number(pageOnly[1]);continue;}
    const periodLine=line.match(/^الحصة\s+(.+?)\s*:\s*$/);
    if(periodLine){
      finishCell();
      if(!teacher)throw new Error("ظهرت حصة قبل اسم المعلم عند السطر "+(i+1)+".");
      const period=parsePeriod(periodLine[1]);
      if(!period)throw new Error("رقم الحصة غير معروف عند السطر "+(i+1)+": "+periodLine[1]);
      if(teacher.cells.some(v=>v.period===period))throw new Error("الحصة "+period+" مكررة للمعلم «"+teacher.sourceName+"».");
      cellStartLine=i+1;cell={period};continue;
    }
    const field=line.match(/^[-•]?\s*(الصف\s*والشعبة|الصف|الشعبة|المادة|الحالة|الملاحظة|ملاحظات)\s*:\s*(.*)$/);
    if(field){
      if(!cell||!teacher)throw new Error("وجدت خانة بيانات دون عنوان حصة عند السطر "+(i+1)+".");
      const key=normalizedKey(field[1]),value=cleanLine(field[2]);
      if(key.startsWith("الصف")||key==="الشعبه")cell.sourceClass=value;
      else if(key==="الماده")cell.sourceSubject=value;
      else if(key==="الحاله")cell.sourceStatus=value;
      else cell.sourceNote=value;
    }
  }
  finishTeacher();
  if(!teachers.length)throw new Error("لم أتعرف على أسماء المعلمين. استخدم «اسم المعلم: الاسم» أو صفوفاً مفصولة بعلامات تبويب.");
  const totalCells=teachers.reduce((sum,v)=>sum+v.cells.length,0);
  const periodCount=teachers[0].cells.length;
  if(![7,8].includes(periodCount)||teachers.some(item=>item.cells.length!==periodCount))throw new Error("يجب أن يحتوي كل معلم على العدد نفسه من الحصص (7 أو 8).");
  return {weekday:day,teachers,totals,totalCells,warnings};
}

/** Availability rules for a complete, explicit weekly timetable grid. */
export interface SubstitutionTeacher { id:string; name:string; departmentId:string; }
export type TimetableCellStatus="teaching"|"free"|"meeting"|"activity"|"other"|"unclear";
export interface TimetableEntry { teacherId:string; weekday:string; period:number; className:string; subject?:string; status?:TimetableCellStatus; }
export interface SubstitutionAssignment { substituteTeacherId:string; weekday:string; period:number; assignmentDate?:string|null; status?:"assigned"|"confirmed"|"cancelled"|"completed"; }
export interface SubstitutionLesson { weekday:string; period:number; className:string; subject?:string; }
export interface CandidateQuery {
  teachers:SubstitutionTeacher[]; timetable:TimetableEntry[]; assignments:SubstitutionAssignment[];
  absentTeacherId:string; weekday:string; period:number; departmentId:string; includeOtherDepartments?:boolean; assignmentDate?:string;
}
function sameCell(a:{weekday:string;period:number},b:{weekday:string;period:number}):boolean {
  return a.weekday===b.weekday && a.period===b.period;
}
/** Only explicit teaching cells are lessons that need a replacement. */
export function getAbsentTeacherLessons(timetable:TimetableEntry[],teacherId:string,weekday:string):SubstitutionLesson[] {
  return timetable.filter(e=>e.teacherId===teacherId && e.weekday===weekday && (e.status??"teaching")==="teaching")
    .map(e=>({weekday:e.weekday,period:e.period,className:e.className,...(e.subject?{subject:e.subject}:{})}))
    .sort((a,b)=>a.period-b.period);
}
/** Missing, duplicated, meeting, activity, other and unclear cells are never treated as free. */
export function getAvailableSubstitutionCandidates(query:CandidateQuery):SubstitutionTeacher[] {
  const {teachers,timetable,assignments,absentTeacherId,weekday,period,departmentId,includeOtherDepartments=false,assignmentDate}=query;
  const cells=new Map<string,{count:number;isFree:boolean}>();
  for(const entry of timetable.filter(e=>sameCell(e,{weekday,period}))){
    const current=cells.get(entry.teacherId)??{count:0,isFree:true};
    current.count+=1;
    if((entry.status??"teaching")!=="free") current.isFree=false;
    cells.set(entry.teacherId,current);
  }
  const activeAssignments=assignments.filter(a=>a.status!=="cancelled");
  const assigned=new Set(activeAssignments.filter(a=>sameCell(a,{weekday,period})&&(!assignmentDate||!a.assignmentDate||a.assignmentDate===assignmentDate)).map(a=>a.substituteTeacherId));
  const workload=new Map<string,number>();
  for(const assignment of activeAssignments) workload.set(assignment.substituteTeacherId,(workload.get(assignment.substituteTeacherId)??0)+1);
  return teachers.filter(t=>t.id!==absentTeacherId)
    .filter(t=>includeOtherDepartments||!!departmentId&&t.departmentId===departmentId)
    .filter(t=>{const cell=cells.get(t.id);return !!cell&&cell.count===1&&cell.isFree;})
    .filter(t=>!assigned.has(t.id)).slice().sort((a,b)=>(workload.get(a.id)??0)-(workload.get(b.id)??0)||a.name.localeCompare(b.name,"ar"));
}
